                </div>
                <div className="rounded border border-slate-200 bg-white p-3">
                  <p className="text-[10px] font-bold tracking-[0.1em] uppercase text-slate-500 mb-2">First-principles decomposition preview</p>
                  <ul className="space-y-1.5">
