#!/usr/bin/env node
import fs from 'node:fs'
import path from 'node:path'
import Stripe from 'stripe'

const DEFAULT_TEMPLATE = path.join(process.cwd(), 'business', 'assets', 'weekly-agent-dashboard-template.csv')
const TMP_DIR = path.join(process.cwd(), 'business', 'assets', 'tmp')

const REQUIRED_POSTHOG_EVENTS = [
  'marketing_page_viewed',
  'demo_brief_generated',
  'signup_completed',
  'trial_started',
  'week2_activated',
  'trial_converted',
]

const POSTHOG_METRIC_KEYS = new Set([
  'global_week2_activation',
  'lifecycle_week2_activation',
  'analytics_event_coverage',
  'analytics_attribution_complete',
  'analytics_break_detect_time',
  'proof_conversion_lift',
])

const STRIPE_METRIC_KEYS = new Set([
  'global_trial_to_paid',
  'lifecycle_trial_paid',
  'global_30d_churn',
])

const HUBSPOT_METRIC_KEYS = new Set([
  'global_new_sales_calls',
  'global_trial_starts',
  'global_outreach_to_call',
  'revops_required_fields',
  'revops_next_step_set',
  'revops_followup_sla',
  'revops_stalled_deals',
  'prospecting_lead_reply',
  'prospecting_personalization',
  'outreach_touch_volume',
  'outreach_positive_reply',
  'outreach_call_booked',
  'outreach_compliance_incidents',
  'enablement_same_day_recap',
  'enablement_objection_improve',
  'lifecycle_human_assist',
  'proof_trigger_send',
  'partner_meetings',
  'partner_meeting_to_pilot',
  'partner_inactive_30d',
  'partner_seat_growth',
])

function parseArgs(argv) {
  const args = argv.slice(2)
  const get = (name) => {
    const prefix = `${name}=`
    const hit = args.find((value) => value.startsWith(prefix))
    return hit ? hit.slice(prefix.length) : null
  }
  return {
    strict: args.includes('--strict'),
    json: args.includes('--json'),
    template: get('--template') ?? DEFAULT_TEMPLATE,
    weekStart: get('--week-start') ?? null,
    out: get('--out') ?? null,
  }
}

function toIsoDate(date) {
  return date.toISOString().slice(0, 10)
}

function getWeekWindow(weekStartArg) {
  if (weekStartArg) {
    const parsed = new Date(`${weekStartArg}T00:00:00.000Z`)
    if (Number.isNaN(parsed.getTime())) {
      throw new Error(`Invalid --week-start value: ${weekStartArg}`)
    }
    const weekEnd = new Date(parsed)
    weekEnd.setUTCDate(weekEnd.getUTCDate() + 7)
    return { weekStart: parsed, weekEnd }
  }

  const now = new Date()
  const utcMidnight = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()))
  const day = utcMidnight.getUTCDay()
  const offsetToMonday = (day + 6) % 7
  const weekStart = new Date(utcMidnight)
  weekStart.setUTCDate(weekStart.getUTCDate() - offsetToMonday)
  const weekEnd = new Date(weekStart)
  weekEnd.setUTCDate(weekEnd.getUTCDate() + 7)
  return { weekStart, weekEnd }
}

function getSnapshotPath(explicitOutPath, weekStart) {
  if (explicitOutPath) {
    return path.resolve(process.cwd(), explicitOutPath)
  }
  return path.join(TMP_DIR, `weekly-dashboard-snapshot-${toIsoDate(weekStart)}.csv`)
}

function parseCsvLine(line) {
  const cells = []
  let current = ''
  let inQuotes = false

  for (let i = 0; i < line.length; i += 1) {
    const char = line[i]
    const next = line[i + 1]

    if (char === '"') {
      if (inQuotes && next === '"') {
        current += '"'
        i += 1
      } else {
        inQuotes = !inQuotes
      }
      continue
    }

    if (char === ',' && !inQuotes) {
      cells.push(current)
      current = ''
      continue
    }

    current += char
  }

  cells.push(current)
  return cells
}

function parseCsv(content) {
  const lines = content.replace(/^\uFEFF/, '').split(/\r?\n/).filter((line) => line.trim().length > 0)
  if (lines.length === 0) return { headers: [], rows: [] }

  const headers = parseCsvLine(lines[0])
  const rows = lines.slice(1).map((line) => {
    const values = parseCsvLine(line)
    const row = {}
    headers.forEach((header, index) => {
      row[header] = values[index] ?? ''
    })
    return row
  })

  return { headers, rows }
}

function csvEscape(value) {
  const stringValue = value == null ? '' : String(value)
  if (!/[",\n\r]/.test(stringValue)) return stringValue
  return `"${stringValue.replace(/"/g, '""')}"`
}

function stringifyCsv(headers, rows) {
  const headerLine = headers.map(csvEscape).join(',')
  const body = rows
    .map((row) => headers.map((header) => csvEscape(row[header] ?? '')).join(','))
    .join('\n')
  return `${headerLine}\n${body}\n`
}

function asNumber(value) {
  if (value == null || value === '') return null
  const numeric = Number(value)
  return Number.isFinite(numeric) ? numeric : null
}

function computeStatus(operator, thresholdRaw, actualRaw) {
  const threshold = asNumber(thresholdRaw)
  const actual = asNumber(actualRaw)

  if (threshold == null || actual == null) {
    return { status: 'PENDING', variance: '' }
  }

  if (operator === '>=') {
    const variance = Number((actual - threshold).toFixed(4))
    return {
      status: actual >= threshold ? 'GREEN' : 'RED',
      variance,
    }
  }

  if (operator === '<=') {
    const variance = Number((threshold - actual).toFixed(4))
    return {
      status: actual <= threshold ? 'GREEN' : 'RED',
      variance,
    }
  }

  return { status: 'PENDING', variance: '' }
}

function buildPosthogUrl(host, projectId) {
  return `${host.replace(/\/$/, '')}/api/projects/${projectId}/query/`
}

async function runPosthogQuery(ctx, query) {
  const response = await fetch(buildPosthogUrl(ctx.host, ctx.projectId), {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${ctx.apiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      query: {
        kind: 'HogQLQuery',
        query,
      },
    }),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`PostHog query failed (${response.status}): ${text.slice(0, 300)}`)
  }

  const data = await response.json()
  return Array.isArray(data.results) ? data.results : []
}

function firstValue(rows, fallback = null) {
  if (!Array.isArray(rows) || rows.length === 0 || !Array.isArray(rows[0]) || rows[0].length === 0) {
    return fallback
  }
  return rows[0][0]
}

function isoUtc(date) {
  return date.toISOString()
}

function buildTimeFilter(weekStart, weekEnd) {
  return `timestamp >= toDateTime('${isoUtc(weekStart)}') AND timestamp < toDateTime('${isoUtc(weekEnd)}')`
}

function buildTrailingFilter(endDate, trailingDays) {
  const start = new Date(endDate)
  start.setUTCDate(start.getUTCDate() - trailingDays)
  return `timestamp >= toDateTime('${isoUtc(start)}') AND timestamp < toDateTime('${isoUtc(endDate)}')`
}

async function getPosthogMetric(metricId, ctx) {
  const weekFilter = buildTimeFilter(ctx.weekStart, ctx.weekEnd)
  const trailing4w = buildTrailingFilter(ctx.weekEnd, 28)

  if (metricId === 'global_week2_activation' || metricId === 'lifecycle_week2_activation') {
    const activated = Number(firstValue(await runPosthogQuery(ctx, `SELECT uniq(distinct_id) FROM events WHERE event='week2_activated' AND ${weekFilter}`), 0) ?? 0)
    const trialUsers = Number(firstValue(await runPosthogQuery(ctx, `SELECT uniq(distinct_id) FROM events WHERE event='trial_started' AND ${weekFilter}`), 0) ?? 0)
    if (trialUsers <= 0) return 0
    return Number(((activated / trialUsers) * 100).toFixed(2))
  }

  if (metricId === 'analytics_event_coverage') {
    const eventList = REQUIRED_POSTHOG_EVENTS.map((event) => `'${event.replace(/'/g, "\\'")}'`).join(',')
    const seenCount = Number(firstValue(await runPosthogQuery(ctx, `SELECT uniq(event) FROM events WHERE event IN (${eventList}) AND ${weekFilter}`), 0) ?? 0)
    return Number(((seenCount / REQUIRED_POSTHOG_EVENTS.length) * 100).toFixed(2))
  }

  if (metricId === 'analytics_attribution_complete') {
    const total = Number(firstValue(await runPosthogQuery(ctx, `SELECT count() FROM events WHERE event IN ('marketing_page_viewed','demo_brief_generated','signup_completed','trial_started') AND ${weekFilter}`), 0) ?? 0)
    if (total <= 0) return 0
    const tagged = Number(firstValue(await runPosthogQuery(ctx, `SELECT count() FROM events WHERE event IN ('marketing_page_viewed','demo_brief_generated','signup_completed','trial_started') AND ${weekFilter} AND length(trim(toString(properties.utm_source))) > 0`), 0) ?? 0)
    return Number(((tagged / total) * 100).toFixed(2))
  }

  if (metricId === 'analytics_break_detect_time') {
    const rows = await runPosthogQuery(ctx, `
      SELECT max(gap_hours)
      FROM (
        SELECT dateDiff('hour', lagInFrame(timestamp) OVER (PARTITION BY event ORDER BY timestamp), timestamp) AS gap_hours
        FROM events
        WHERE event IN ('marketing_page_viewed','trial_started','week2_activated','trial_converted') AND ${trailing4w}
      )
      WHERE gap_hours IS NOT NULL
    `)
    const maxGap = Number(firstValue(rows, 0) ?? 0)
    return Number.isFinite(maxGap) ? Number(maxGap.toFixed(2)) : 0
  }

  if (metricId === 'proof_conversion_lift') {
    const withProof = Number(firstValue(await runPosthogQuery(ctx, `SELECT count() FROM events WHERE event='trial_started' AND ${trailing4w} AND toInt(properties.proof_variant_seen)=1`), 0) ?? 0)
    const withoutProof = Number(firstValue(await runPosthogQuery(ctx, `SELECT count() FROM events WHERE event='trial_started' AND ${trailing4w} AND toInt(properties.proof_variant_seen)=0`), 0) ?? 0)
    if (withoutProof <= 0) return 0
    return Number((((withProof - withoutProof) / withoutProof) * 100).toFixed(2))
  }

  return null
}

async function searchHubspotObjectCount(ctx, objectType, filterGroups) {
  const endpoint = `${ctx.baseUrl.replace(/\/$/, '')}/crm/v3/objects/${objectType}/search`
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${ctx.token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      filterGroups,
      limit: 1,
      properties: [],
    }),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`HubSpot ${objectType} search failed (${response.status}): ${text.slice(0, 300)}`)
  }

  const data = await response.json()
  return Number(data.total ?? 0)
}

async function safeHubspotObjectCount(ctx, objectType, filterGroups) {
  try {
    return await searchHubspotObjectCount(ctx, objectType, filterGroups)
  } catch {
    return null
  }
}

async function searchHubspotObjects(ctx, objectType, filterGroups, properties = [], limit = 100) {
  const endpoint = `${ctx.baseUrl.replace(/\/$/, '')}/crm/v3/objects/${objectType}/search`
  const results = []
  let after = undefined

  while (true) {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${ctx.token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        filterGroups,
        limit,
        after,
        properties,
      }),
    })

    if (!response.ok) {
      const text = await response.text().catch(() => '')
      throw new Error(`HubSpot ${objectType} search failed (${response.status}): ${text.slice(0, 300)}`)
    }

    const data = await response.json()
    const page = Array.isArray(data.results) ? data.results : []
    results.push(...page)

    const nextAfter = data?.paging?.next?.after
    if (!nextAfter) break
    after = nextAfter
  }

  return results
}

async function safeHubspotObjects(ctx, objectType, filterGroups, properties = [], limit = 100) {
  try {
    return await searchHubspotObjects(ctx, objectType, filterGroups, properties, limit)
  } catch {
    return null
  }
}

function isTruthyString(value) {
  return typeof value === 'string' && value.trim().length > 0
}

async function getTrialStartedStageId(ctx) {
  if (ctx.trialStartedStageId) return ctx.trialStartedStageId
  if (ctx.derivedTrialStageId !== undefined) return ctx.derivedTrialStageId

  const endpoint = `${ctx.baseUrl.replace(/\/$/, '')}/crm/v3/pipelines/deals`
  const response = await fetch(endpoint, {
    headers: {
      Authorization: `Bearer ${ctx.token}`,
      'Content-Type': 'application/json',
    },
  })

  if (!response.ok) {
    ctx.derivedTrialStageId = null
    return null
  }

  const data = await response.json()
  const pipelines = Array.isArray(data.results) ? data.results : []
  for (const pipeline of pipelines) {
    const stages = Array.isArray(pipeline?.stages) ? pipeline.stages : []
    for (const stage of stages) {
      const label = String(stage?.label ?? '').toLowerCase()
      const id = String(stage?.id ?? '')
      if (label.includes('trial') && id) {
        ctx.derivedTrialStageId = id
        return id
      }
    }
  }

  ctx.derivedTrialStageId = null
  return null
}

function epochMs(date) {
  return String(date.getTime())
}

function parseDateLike(value) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return new Date(value)
  }
  if (typeof value === 'string' && value.trim().length > 0) {
    const asNumber = Number(value)
    if (Number.isFinite(asNumber) && asNumber > 0) {
      return new Date(asNumber)
    }
    const parsed = new Date(value)
    if (!Number.isNaN(parsed.getTime())) return parsed
  }
  return null
}

function withinWindow(date, start, end) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return false
  return date >= start && date < end
}

function safeLower(value) {
  return typeof value === 'string' ? value.toLowerCase() : ''
}

async function getOpenDeals(ctx, properties) {
  const baseFilters = [
    {
      filters: [
        { propertyName: 'hs_is_closed', operator: 'EQ', value: 'false' },
      ],
    },
  ]

  const openDeals = await searchHubspotObjects(ctx, 'deals', baseFilters, properties).catch(() => null)
  if (Array.isArray(openDeals)) return openDeals

  // Fallback when hs_is_closed isn't filterable in a portal.
  return searchHubspotObjects(ctx, 'deals', [], properties)
}

async function getActivitiesForWeek(ctx, properties = []) {
  return safeHubspotObjects(ctx, 'activities', [
    {
      filters: [
        { propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: epochMs(ctx.weekStart) },
        { propertyName: 'hs_lastmodifieddate', operator: 'LT', value: epochMs(ctx.weekEnd) },
      ],
    },
  ], properties)
}

async function getTasksForWeek(ctx, properties = []) {
  return safeHubspotObjects(ctx, 'tasks', [
    {
      filters: [
        { propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: epochMs(ctx.weekStart) },
        { propertyName: 'hs_lastmodifieddate', operator: 'LT', value: epochMs(ctx.weekEnd) },
      ],
    },
  ], properties)
}

async function getHubspotMetric(metricKey, ctx) {
  const fromMs = epochMs(ctx.weekStart)
  const toMs = epochMs(ctx.weekEnd)

  if (metricKey === 'global_new_sales_calls') {
    const completedAttempt = await safeHubspotObjectCount(ctx, 'meetings', [
      {
        filters: [
          { propertyName: 'hs_timestamp', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_timestamp', operator: 'LT', value: toMs },
          { propertyName: 'hs_meeting_outcome', operator: 'EQ', value: 'COMPLETED' },
        ],
      },
    ])

    if (typeof completedAttempt === 'number') return completedAttempt

    const meetingsFallback = await safeHubspotObjectCount(ctx, 'meetings', [
      {
        filters: [
          { propertyName: 'hs_timestamp', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_timestamp', operator: 'LT', value: toMs },
        ],
      },
    ])

    if (typeof meetingsFallback === 'number') return meetingsFallback

    // Some portals expose appointment objects but not meetings search.
    const appointmentsFallback = await safeHubspotObjectCount(ctx, 'appointments', [
      {
        filters: [
          { propertyName: 'hs_timestamp', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_timestamp', operator: 'LT', value: toMs },
        ],
      },
    ])

    if (typeof appointmentsFallback === 'number') return appointmentsFallback
    return null
  }

  if (metricKey === 'global_trial_starts') {
    const trialStageId = await getTrialStartedStageId(ctx)
    if (!trialStageId) return null
    return searchHubspotObjectCount(ctx, 'deals', [
      {
        filters: [
          { propertyName: 'dealstage', operator: 'EQ', value: trialStageId },
          { propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_lastmodifieddate', operator: 'LT', value: toMs },
        ],
      },
    ])
  }

  if (metricKey === 'global_outreach_to_call') {
    const touchCount = await getHubspotMetric('outreach_touch_volume', ctx)
    const callBooked = await getHubspotMetric('outreach_call_booked', ctx)
    if (typeof touchCount !== 'number' || typeof callBooked !== 'number') return null
    if (touchCount <= 0) return 0
    return Number(((callBooked / touchCount) * 100).toFixed(2))
  }

  if (metricKey === 'revops_required_fields') {
    const openDeals = await getOpenDeals(ctx, ['dealname', 'dealstage', 'pipeline', 'hubspot_owner_id', 'hs_next_step'])
    if (openDeals.length === 0) return 100

    const complete = openDeals.filter((deal) => {
      const p = deal?.properties ?? {}
      return isTruthyString(p.dealname)
        && isTruthyString(p.dealstage)
        && isTruthyString(p.pipeline)
        && isTruthyString(p.hubspot_owner_id)
        && isTruthyString(p.hs_next_step)
    }).length

    return Number(((complete / openDeals.length) * 100).toFixed(2))
  }

  if (metricKey === 'revops_next_step_set') {
    const openDeals = await getOpenDeals(ctx, ['hs_next_step'])
    if (openDeals.length === 0) return 100

    const withNextStep = openDeals.filter((deal) => isTruthyString(deal?.properties?.hs_next_step)).length
    return Number(((withNextStep / openDeals.length) * 100).toFixed(2))
  }

  if (metricKey === 'revops_followup_sla') {
    const tasks = await getTasksForWeek(ctx, ['hs_due_date', 'hs_completed_at', 'hs_task_status'])
    if (!Array.isArray(tasks)) return null

    const completed = tasks.filter((task) => {
      const p = task?.properties ?? {}
      const status = safeLower(p.hs_task_status)
      return status.includes('completed') || status.includes('done') || Boolean(p.hs_completed_at)
    })

    if (completed.length === 0) return 100

    const withinSla = completed.filter((task) => {
      const p = task?.properties ?? {}
      const due = parseDateLike(p.hs_due_date)
      const completedAt = parseDateLike(p.hs_completed_at)
      if (!completedAt) return false
      if (!due) return true
      return completedAt.getTime() - due.getTime() <= (24 * 60 * 60 * 1000)
    }).length

    return Number(((withinSla / completed.length) * 100).toFixed(2))
  }

  if (metricKey === 'revops_stalled_deals') {
    const staleCutoff = new Date(ctx.weekEnd)
    staleCutoff.setUTCDate(staleCutoff.getUTCDate() - 7)

    const openDeals = await getOpenDeals(ctx, ['hs_lastmodifieddate'])
    return openDeals.filter((deal) => {
      const lastModified = Number(deal?.properties?.hs_lastmodifieddate ?? 0)
      return Number.isFinite(lastModified) && lastModified > 0 && lastModified < staleCutoff.getTime()
    }).length
  }

  if (metricKey === 'prospecting_personalization') {
    const contacts = await safeHubspotObjects(ctx, 'contacts', [
      {
        filters: [
          { propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_lastmodifieddate', operator: 'LT', value: toMs },
        ],
      },
    ], ['jobtitle', 'company'])

    if (!Array.isArray(contacts)) return null

    if (contacts.length === 0) return 0
    const withSignal = contacts.filter((contact) => {
      const p = contact?.properties ?? {}
      return isTruthyString(p.jobtitle) || isTruthyString(p.company)
    }).length
    return Number(((withSignal / contacts.length) * 100).toFixed(2))
  }

  if (metricKey === 'prospecting_lead_reply') {
    const activities = await getActivitiesForWeek(ctx, ['hs_activity_type', 'hs_subject', 'hs_body_preview'])
    if (!Array.isArray(activities)) return null

    const outreach = activities.filter((row) => {
      const p = row?.properties ?? {}
      const type = safeLower(p.hs_activity_type)
      return type.includes('email') || type.includes('call') || type.includes('linkedin')
    })

    if (outreach.length === 0) return 0

    const replies = activities.filter((row) => {
      const p = row?.properties ?? {}
      const subject = safeLower(p.hs_subject)
      const body = safeLower(p.hs_body_preview)
      return subject.includes('re:') || body.includes('reply') || body.includes('responded')
    })

    return Number(((replies.length / outreach.length) * 100).toFixed(2))
  }

  if (metricKey === 'outreach_touch_volume') {
    const activities = await getActivitiesForWeek(ctx, ['hs_activity_type'])
    if (!Array.isArray(activities)) return null
    return activities.filter((row) => {
      const type = safeLower(row?.properties?.hs_activity_type)
      return type.includes('email') || type.includes('call') || type.includes('linkedin') || type.includes('sms')
    }).length
  }

  if (metricKey === 'outreach_positive_reply') {
    const activities = await getActivitiesForWeek(ctx, ['hs_subject', 'hs_body_preview'])
    if (!Array.isArray(activities)) return null

    const touchCount = await getHubspotMetric('outreach_touch_volume', ctx)
    if (typeof touchCount !== 'number' || touchCount <= 0) return 0

    const positiveReplies = activities.filter((row) => {
      const p = row?.properties ?? {}
      const text = `${safeLower(p.hs_subject)} ${safeLower(p.hs_body_preview)}`
      return text.includes('interested') || text.includes('sounds good') || text.includes('let\'s talk') || text.includes('book')
    }).length

    return Number(((positiveReplies / touchCount) * 100).toFixed(2))
  }

  if (metricKey === 'outreach_call_booked') {
    const touchCount = await getHubspotMetric('outreach_touch_volume', ctx)
    if (typeof touchCount !== 'number' || touchCount <= 0) return 0

    const calls = await getHubspotMetric('global_new_sales_calls', ctx)
    if (typeof calls !== 'number') return null
    return Number(((calls / touchCount) * 100).toFixed(2))
  }

  if (metricKey === 'outreach_compliance_incidents') {
    const activities = await getActivitiesForWeek(ctx, ['hs_subject', 'hs_body_preview'])
    if (!Array.isArray(activities)) return null

    return activities.filter((row) => {
      const p = row?.properties ?? {}
      const text = `${safeLower(p.hs_subject)} ${safeLower(p.hs_body_preview)}`
      return text.includes('unsubscribe') || text.includes('do not contact') || text.includes('spam')
    }).length
  }

  if (metricKey === 'enablement_same_day_recap') {
    const calls = await safeHubspotObjects(ctx, 'meetings', [
      {
        filters: [
          { propertyName: 'hs_timestamp', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_timestamp', operator: 'LT', value: toMs },
        ],
      },
    ], ['hs_timestamp'])
    if (!Array.isArray(calls)) return null
    if (calls.length === 0) return 100

    const activities = await getActivitiesForWeek(ctx, ['hs_timestamp', 'hs_subject', 'hs_body_preview'])
    if (!Array.isArray(activities)) return null

    const recapCount = calls.filter((call) => {
      const callTime = parseDateLike(call?.properties?.hs_timestamp)
      if (!callTime) return false
      const windowEnd = new Date(callTime)
      windowEnd.setUTCHours(23, 59, 59, 999)

      return activities.some((activity) => {
        const p = activity?.properties ?? {}
        const ts = parseDateLike(p.hs_timestamp)
        const text = `${safeLower(p.hs_subject)} ${safeLower(p.hs_body_preview)}`
        if (!ts) return false
        if (ts < callTime || ts > windowEnd) return false
        return text.includes('recap') || text.includes('summary') || text.includes('next steps')
      })
    }).length

    return Number(((recapCount / calls.length) * 100).toFixed(2))
  }

  if (metricKey === 'enablement_objection_improve') {
    // Requires objection tagging in CRM; until standardized, return 0 trend delta.
    return 0
  }

  if (metricKey === 'lifecycle_human_assist') {
    const trialStageId = await getTrialStartedStageId(ctx)
    if (!trialStageId) return null

    const trialDeals = await safeHubspotObjects(ctx, 'deals', [
      {
        filters: [
          { propertyName: 'dealstage', operator: 'EQ', value: trialStageId },
          { propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_lastmodifieddate', operator: 'LT', value: toMs },
        ],
      },
    ], ['dealname'])
    if (!Array.isArray(trialDeals)) return null
    if (trialDeals.length === 0) return 0

    const activities = await getActivitiesForWeek(ctx, ['hs_activity_type', 'hs_subject', 'hs_body_preview'])
    if (!Array.isArray(activities)) return null

    const assistSignals = activities.filter((row) => {
      const p = row?.properties ?? {}
      const type = safeLower(p.hs_activity_type)
      const text = `${safeLower(p.hs_subject)} ${safeLower(p.hs_body_preview)}`
      return type.includes('call') || type.includes('meeting') || text.includes('assist') || text.includes('helped')
    }).length

    const ratio = Math.min(assistSignals / trialDeals.length, 1)
    return Number((ratio * 100).toFixed(2))
  }

  if (metricKey === 'proof_trigger_send') {
    const activities = await getActivitiesForWeek(ctx, ['hs_subject', 'hs_body_preview'])
    if (!Array.isArray(activities)) return null

    const proofAsks = activities.filter((row) => {
      const p = row?.properties ?? {}
      const text = `${safeLower(p.hs_subject)} ${safeLower(p.hs_body_preview)}`
      return text.includes('review') || text.includes('testimonial') || text.includes('feedback')
    }).length

    const trialStageId = await getTrialStartedStageId(ctx)
    if (!trialStageId) return null
    const trialDeals = await safeHubspotObjectCount(ctx, 'deals', [
      {
        filters: [
          { propertyName: 'dealstage', operator: 'EQ', value: trialStageId },
          { propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_lastmodifieddate', operator: 'LT', value: toMs },
        ],
      },
    ])
    if (typeof trialDeals !== 'number') return null
    if (trialDeals <= 0) return 0

    return Number(((proofAsks / trialDeals) * 100).toFixed(2))
  }

  if (metricKey === 'partner_meetings') {
    if (ctx.partnerMeetingTag) {
      const taggedMeetings = await safeHubspotObjectCount(ctx, 'meetings', [
        {
          filters: [
            { propertyName: 'hs_timestamp', operator: 'GTE', value: fromMs },
            { propertyName: 'hs_timestamp', operator: 'LT', value: toMs },
            { propertyName: 'hs_meeting_title', operator: 'CONTAINS_TOKEN', value: ctx.partnerMeetingTag },
          ],
        },
      ])

      if (typeof taggedMeetings === 'number') return taggedMeetings
      return null
    }

    // Heuristic fallback: classify appointments with "partner" or "coach" in title as partner meetings.
    const appointments = await safeHubspotObjects(ctx, 'appointments', [
      {
        filters: [
          { propertyName: 'hs_timestamp', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_timestamp', operator: 'LT', value: toMs },
        ],
      },
    ], ['hs_meeting_title', 'hs_appointment_title', 'hs_title'])

    if (!Array.isArray(appointments)) return null

    return appointments.filter((row) => {
      const p = row?.properties ?? {}
      const title = `${p.hs_meeting_title ?? ''} ${p.hs_appointment_title ?? ''} ${p.hs_title ?? ''}`.toLowerCase()
      return title.includes('partner') || title.includes('coach')
    }).length
  }

  if (metricKey === 'partner_meeting_to_pilot') {
    const meetings = await getHubspotMetric('partner_meetings', ctx)
    if (typeof meetings !== 'number') return null
    if (meetings <= 0) return 0

    const deals = await safeHubspotObjects(ctx, 'deals', [
      {
        filters: [
          { propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: fromMs },
          { propertyName: 'hs_lastmodifieddate', operator: 'LT', value: toMs },
        ],
      },
    ], ['dealname', 'dealstage'])
    if (!Array.isArray(deals)) return null

    const pilots = deals.filter((deal) => {
      const p = deal?.properties ?? {}
      const text = `${safeLower(p.dealname)} ${safeLower(p.dealstage)}`
      return text.includes('pilot') && (text.includes('partner') || text.includes('coach'))
    }).length

    return Number(((pilots / meetings) * 100).toFixed(2))
  }

  if (metricKey === 'partner_inactive_30d') {
    const cutoff = new Date(ctx.weekEnd)
    cutoff.setUTCDate(cutoff.getUTCDate() - 30)

    const deals = await safeHubspotObjects(ctx, 'deals', [], ['dealname', 'hs_lastmodifieddate'])
    if (!Array.isArray(deals)) return null

    return deals.filter((deal) => {
      const p = deal?.properties ?? {}
      const label = safeLower(p.dealname)
      if (!label.includes('partner') && !label.includes('coach')) return false
      const lastModified = parseDateLike(p.hs_lastmodifieddate)
      return lastModified ? lastModified < cutoff : false
    }).length
  }

  if (metricKey === 'partner_seat_growth') {
    const trailingStart = new Date(ctx.weekEnd)
    trailingStart.setUTCDate(trailingStart.getUTCDate() - 31)

    const subscriptions = await listStripeSubscriptions(ctx.stripeCtx, unix(trailingStart), unix(ctx.weekEnd))
    const partnerSubs = subscriptions.filter((sub) => {
      const md = sub.metadata ?? {}
      const role = safeLower(md.partner || md.channel || md.source)
      return role.includes('partner') || role.includes('coach')
    })
    if (partnerSubs.length === 0) return 0

    const midpoint = new Date(ctx.weekEnd)
    midpoint.setUTCDate(midpoint.getUTCDate() - 15)

    const early = partnerSubs.filter((sub) => (sub.created ?? 0) < unix(midpoint)).length
    const late = partnerSubs.filter((sub) => (sub.created ?? 0) >= unix(midpoint)).length
    return late - early
  }

  return null
}

async function listStripeSubscriptions(ctx, createdGte, createdLt) {
  const subs = []
  let hasMore = true
  let startingAfter = undefined

  while (hasMore) {
    const page = await ctx.client.subscriptions.list({
      limit: 100,
      created: { gte: createdGte, lt: createdLt },
      status: 'all',
      starting_after: startingAfter,
    })
    subs.push(...page.data)
    hasMore = page.has_more
    startingAfter = page.data.length > 0 ? page.data[page.data.length - 1].id : undefined
    if (!startingAfter) break
  }

  return subs
}

function unix(date) {
  return Math.floor(date.getTime() / 1000)
}

async function getStripeMetric(metricId, ctx) {
  const trailing4wStart = new Date(ctx.weekEnd)
  trailing4wStart.setUTCDate(trailing4wStart.getUTCDate() - 28)

  const subs = await listStripeSubscriptions(ctx, unix(trailing4wStart), unix(ctx.weekEnd))

  if (metricId === 'global_trial_to_paid' || metricId === 'lifecycle_trial_paid') {
    const trialSubs = subs.filter((sub) => sub.trial_start && sub.trial_end)
    const converted = trialSubs.filter((sub) => {
      const activeLike = ['active', 'past_due', 'unpaid'].includes(sub.status)
      return activeLike && (sub.trial_end ?? 0) < unix(ctx.weekEnd)
    })
    if (trialSubs.length === 0) return 0
    return Number(((converted.length / trialSubs.length) * 100).toFixed(2))
  }

  if (metricId === 'global_30d_churn') {
    const paidSubs = subs.filter((sub) => !sub.trial_start || sub.status !== 'trialing')
    if (paidSubs.length === 0) return 0
    const churned = paidSubs.filter((sub) => sub.canceled_at && sub.created && (sub.canceled_at - sub.created) <= (30 * 24 * 60 * 60))
    return Number(((churned.length / paidSubs.length) * 100).toFixed(2))
  }

  return null
}

function buildProviderContexts(weekStart, weekEnd) {
  const posthogProjectId = (process.env.POSTHOG_PROJECT_ID ?? '').trim()
  const posthogApiKey = (process.env.POSTHOG_PERSONAL_API_KEY ?? '').trim()
  const posthogHost = (process.env.POSTHOG_HOST || process.env.NEXT_PUBLIC_POSTHOG_HOST || 'https://us.i.posthog.com').trim()

  const hubspotToken = (process.env.HUBSPOT_PRIVATE_APP_TOKEN ?? '').trim()
  const hubspotBaseUrl = (process.env.HUBSPOT_BASE_URL || 'https://api.hubapi.com').trim()
  const hubspotTrialStartedStageId = (process.env.HUBSPOT_TRIAL_STARTED_STAGE_ID ?? '').trim()
  const hubspotPartnerMeetingTag = (process.env.HUBSPOT_PARTNER_MEETING_TAG ?? '').trim()

  const stripeSecretKey = (process.env.STRIPE_SECRET_KEY ?? '').trim()

  return {
    posthog: posthogProjectId && posthogApiKey
      ? {
          available: true,
          ctx: {
            projectId: posthogProjectId,
            apiKey: posthogApiKey,
            host: posthogHost,
            weekStart,
            weekEnd,
          },
          missing: [],
        }
      : {
          available: false,
          ctx: null,
          missing: [
            !posthogProjectId ? 'POSTHOG_PROJECT_ID' : null,
            !posthogApiKey ? 'POSTHOG_PERSONAL_API_KEY' : null,
          ].filter(Boolean),
        },

    hubspot: hubspotToken
      ? {
          available: true,
          ctx: {
            token: hubspotToken,
            baseUrl: hubspotBaseUrl,
            trialStartedStageId: hubspotTrialStartedStageId || null,
            partnerMeetingTag: hubspotPartnerMeetingTag || null,
            weekStart,
            weekEnd,
          },
          missing: [],
        }
      : {
          available: false,
          ctx: null,
          missing: ['HUBSPOT_PRIVATE_APP_TOKEN'],
        },

    stripe: stripeSecretKey
      ? {
          available: true,
          ctx: {
            client: new Stripe(stripeSecretKey, { apiVersion: '2026-05-27.dahlia' }),
            weekStart,
            weekEnd,
          },
          missing: [],
        }
      : {
          available: false,
          ctx: null,
          missing: ['STRIPE_SECRET_KEY'],
        },
  }
}

async function resolveMetricValue(row, providers) {
  const source = String(row.source_system ?? '').trim().toLowerCase()
  const metricKey = String(row.metric_key ?? '').trim()

  if (POSTHOG_METRIC_KEYS.has(metricKey)) {
    if (!providers.posthog.available) return { value: null, reason: `missing env: ${providers.posthog.missing.join(', ')}` }
    const value = await getPosthogMetric(metricKey, providers.posthog.ctx)
    return value == null ? { value: null, reason: 'no resolver implemented' } : { value }
  }

  if (STRIPE_METRIC_KEYS.has(metricKey)) {
    if (!providers.stripe.available) return { value: null, reason: `missing env: ${providers.stripe.missing.join(', ')}` }
    const value = await getStripeMetric(metricKey, providers.stripe.ctx)
    return value == null ? { value: null, reason: 'no resolver implemented' } : { value }
  }

  if (HUBSPOT_METRIC_KEYS.has(metricKey)) {
    if (!providers.hubspot.available) return { value: null, reason: `missing env: ${providers.hubspot.missing.join(', ')}` }
    const value = await getHubspotMetric(metricKey, {
      ...providers.hubspot.ctx,
      stripeCtx: providers.stripe.available ? providers.stripe.ctx : null,
    })
    return value == null ? { value: null, reason: 'no resolver implemented or missing optional stage/tag env' } : { value }
  }

  if (source.includes('posthog')) {
    if (!providers.posthog.available) return { value: null, reason: `missing env: ${providers.posthog.missing.join(', ')}` }
    const value = await getPosthogMetric(metricKey, providers.posthog.ctx)
    return value == null ? { value: null, reason: 'no resolver implemented' } : { value }
  }

  if (source.includes('hubspot')) {
    if (!providers.hubspot.available) return { value: null, reason: `missing env: ${providers.hubspot.missing.join(', ')}` }
    const value = await getHubspotMetric(metricKey, {
      ...providers.hubspot.ctx,
      stripeCtx: providers.stripe.available ? providers.stripe.ctx : null,
    })
    return value == null ? { value: null, reason: 'no resolver implemented or missing optional stage/tag env' } : { value }
  }

  if (source.includes('stripe')) {
    if (!providers.stripe.available) return { value: null, reason: `missing env: ${providers.stripe.missing.join(', ')}` }
    const value = await getStripeMetric(metricKey, providers.stripe.ctx)
    return value == null ? { value: null, reason: 'no resolver implemented' } : { value }
  }

  return { value: null, reason: 'manual or unsupported source' }
}

async function generateSnapshot({ templatePath, outPath, weekStart, weekEnd, strict }) {
  if (!fs.existsSync(templatePath)) {
    throw new Error(`Template CSV not found: ${templatePath}`)
  }

  const parsed = parseCsv(fs.readFileSync(templatePath, 'utf8'))
  const providers = buildProviderContexts(weekStart, weekEnd)

  const unresolved = []
  const failures = []

  const nextRows = []
  for (const row of parsed.rows) {
    const next = { ...row }
    if (!next.week_start) {
      next.week_start = toIsoDate(weekStart)
    }

    const { value, reason } = await resolveMetricValue(next, providers)
    if (value == null) {
      if (reason && String(next.source_system).match(/hubspot|posthog|stripe/i)) {
        unresolved.push({ metric_key: next.metric_key, source_system: next.source_system, reason })
      }
    } else {
      next.actual_value = String(value)
    }

    const { status, variance } = computeStatus(next.threshold_operator, next.threshold_value, next.actual_value)
    next.status = status
    next.variance_to_threshold = variance === '' ? '' : String(variance)
    nextRows.push(next)
  }

  fs.mkdirSync(path.dirname(outPath), { recursive: true })
  fs.writeFileSync(outPath, stringifyCsv(parsed.headers, nextRows))

  if (strict && unresolved.length > 0) {
    failures.push(`${unresolved.length} provider-backed metrics unresolved`)
  }

  return {
    outPath,
    week_start: toIsoDate(weekStart),
    week_end_exclusive: toIsoDate(weekEnd),
    rows_total: nextRows.length,
    resolved_count: nextRows.filter((row) => asNumber(row.actual_value) != null).length,
    unresolved_count: unresolved.length,
    unresolved,
    failures,
    provider_status: {
      posthog: providers.posthog.available ? 'connected' : `missing ${providers.posthog.missing.join(', ')}`,
      hubspot: providers.hubspot.available ? 'connected' : `missing ${providers.hubspot.missing.join(', ')}`,
      stripe: providers.stripe.available ? 'connected' : `missing ${providers.stripe.missing.join(', ')}`,
    },
  }
}

async function main() {
  const args = parseArgs(process.argv)
  const { weekStart, weekEnd } = getWeekWindow(args.weekStart)
  const outPath = getSnapshotPath(args.out, weekStart)

  const summary = await generateSnapshot({
    templatePath: path.resolve(process.cwd(), args.template),
    outPath,
    weekStart,
    weekEnd,
    strict: args.strict,
  })

  if (args.json) {
    console.log(JSON.stringify(summary, null, 2))
  } else {
    console.log('Weekly agent dashboard snapshot exported')
    console.log(`Output: ${summary.outPath}`)
    console.log(`Week start: ${summary.week_start}`)
    console.log(`Resolved metrics: ${summary.resolved_count}/${summary.rows_total}`)
    console.log(`Provider status: PostHog=${summary.provider_status.posthog}, HubSpot=${summary.provider_status.hubspot}, Stripe=${summary.provider_status.stripe}`)
    if (summary.unresolved_count > 0) {
      console.log(`Unresolved provider metrics: ${summary.unresolved_count}`)
      for (const item of summary.unresolved.slice(0, 10)) {
        console.log(`- ${item.metric_key}: ${item.reason}`)
      }
      if (summary.unresolved_count > 10) {
        console.log(`- ... ${summary.unresolved_count - 10} more`) 
      }
    }
  }

  if (args.strict && summary.failures.length > 0) {
    console.error(summary.failures.join('; '))
    process.exit(2)
  }
}

main().catch((error) => {
  const message = error instanceof Error ? error.message : String(error)
  console.error(message)
  process.exit(1)
})

'use client'
import { useEffect, useRef, useState, useTransition, type KeyboardEvent as ReactKeyboardEvent } from 'react'
import Link from 'next/link'
import { rateTrace } from './actions'
import { buildFailureSummaryPayload } from './copy-summary'
import { resolveNextActiveRowId } from './active-row'
import {
  buildUrl,
  composeEvalNotes,
  FEATURE_LABELS,
  FEATURES,
  FAILURE_CATEGORIES,
  parseEvalNotes,
  type BulkApplyUndoChange,
  type LastActionState,
  type ToastState,
  type Trace,
} from './trace-shared'

function TraceRow({
  trace,
  enableShortcuts,
  shortcutsBlocked,
  denseMode,
  rowRef,
  onActivate,
  onRated,
}: {
  trace: Trace
  enableShortcuts: boolean
  shortcutsBlocked?: boolean
  denseMode: boolean
  rowRef?: (element: HTMLDivElement | null) => void
  onActivate?: (traceId: string) => void
  onRated?: (traceId: string, prevPass: boolean | null, nextPass: boolean | null, categories: string[]) => void
}) {
  const parsedNotes = parseEvalNotes(trace.eval_notes)
  const [evalPass, setEvalPass]   = useState(trace.eval_pass)
  const [evalNotesBody, setEvalNotesBody] = useState(parsedNotes.body)
  const [categories, setCategories] = useState(parsedNotes.categories)
  const [expanded, setExpanded]   = useState(false)
  const [, startTransition]       = useTransition()

  function persist(nextPass: boolean | null, nextNotesBody: string, nextCategories: string[]) {
    const nextNotes = composeEvalNotes(nextNotesBody, nextCategories)
    startTransition(async () => { await rateTrace(trace.id, nextPass, nextNotes) })
  }

  function setRating(nextPass: boolean | null) {
    const prevPass = evalPass
    setEvalPass(nextPass)
    persist(nextPass, evalNotesBody, categories)
    onRated?.(trace.id, prevPass, nextPass, categories)
  }

  function toggleCategory(category: string) {
    const nextCategories = categories.includes(category)
      ? categories.filter((item) => item !== category)
      : [...categories, category]

    setCategories(nextCategories)
    persist(evalPass, evalNotesBody, nextCategories)
    if (evalPass === false) {
      onRated?.(trace.id, false, false, nextCategories)
    }
  }

  function saveNotes() {
    persist(evalPass, evalNotesBody, categories)
  }

  useEffect(() => {
    if (!enableShortcuts || shortcutsBlocked) return

    function onKeyDown(event: KeyboardEvent) {
      const target = event.target as HTMLElement | null
      if (target) {
        const tagName = target.tagName.toLowerCase()
        if (tagName === 'textarea' || tagName === 'input' || tagName === 'select' || target.isContentEditable) return
      }

      if (event.key.toLowerCase() === 'p') {
        event.preventDefault()
        setRating(true)
      } else if (event.key.toLowerCase() === 'f') {
        event.preventDefault()
        setRating(false)
      } else if (event.key.toLowerCase() === 'u') {
        event.preventDefault()
        setRating(null)
      } else if (event.key.toLowerCase() === 'o') {
        event.preventDefault()
        setExpanded((value) => !value)
      } else if (/^[1-8]$/.test(event.key) && evalPass === false) {
        event.preventDefault()
        const idx = Number(event.key) - 1
        const category = FAILURE_CATEGORIES[idx]
        if (category) {
          toggleCategory(category)
        }
      }
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [enableShortcuts, shortcutsBlocked, evalNotesBody, categories, evalPass])

  const tokens = (trace.prompt_tokens ?? 0) + (trace.completion_tokens ?? 0)
  const dateStr = new Date(trace.created_at).toLocaleString('en-US', {
    month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit',
  })

  const featureLabel = FEATURE_LABELS[trace.feature] ?? trace.feature.replace(/_/g, ' ')

  return (
    <div
      ref={rowRef}
      className={`border-b border-white/10 ${evalPass === true ? 'bg-emerald-50/30' : evalPass === false ? 'bg-red-50/30' : ''} ${enableShortcuts ? 'ring-1 ring-slate-300 ring-inset' : ''}`}
      onMouseDown={() => onActivate?.(trace.id)}
    >
      <div className="px-5 py-4 flex items-start gap-4">

        {/* Pass / Fail column */}
        <div className="flex flex-col gap-1.5 shrink-0 pt-0.5">
          <button
            type="button"
            onClick={() => setRating(evalPass === true ? null : true)}
            aria-keyshortcuts="P"
            className={`px-3 py-1.5 rounded text-[12px] font-bold cursor-pointer border-0 transition-colors w-14 ${
              evalPass === true
                ? 'bg-emerald-500 text-white'
                : 'bg-slate-100 text-slate-400 hover:bg-emerald-50 hover:text-emerald-700'
            }`}
          >
            Pass
          </button>
          <button
            type="button"
            onClick={() => setRating(evalPass === false ? null : false)}
            aria-keyshortcuts="F"
            className={`px-3 py-1.5 rounded text-[12px] font-bold cursor-pointer border-0 transition-colors w-14 ${
              evalPass === false
                ? 'bg-red-500 text-white'
                : 'bg-slate-100 text-slate-400 hover:bg-red-50 hover:text-red-700'
            }`}
          >
            Fail
          </button>
        </div>

        {/* Content column */}
        <div className="flex-1 min-w-0">

          {/* Metadata row */}
          <div className="flex items-center gap-3 flex-wrap mb-2.5">
            <span className="text-[11px] font-bold tracking-[0.08em] uppercase text-slate-300">
              {featureLabel}
            </span>
            {enableShortcuts && (
              <span className="text-[10px] font-bold tracking-[0.08em] uppercase text-slate-200 bg-slate-200 px-2 py-0.5 rounded">
                Active
              </span>
            )}
            <span className="text-[11px] text-slate-400">{dateStr}</span>
            {trace.latency_ms != null && (
              <span className="text-[11px] text-slate-300">{(trace.latency_ms / 1000).toFixed(1)}s</span>
            )}
            {tokens > 0 && (
              <span className="text-[11px] text-slate-300">{tokens.toLocaleString()} tok</span>
            )}
            {trace.user_id && (
              <span className="text-[11px] font-mono text-slate-200">{trace.user_id.slice(0, 8)}</span>
            )}
          </div>

          {/* Input snapshot */}
          {!denseMode && trace.input_snapshot && Object.keys(trace.input_snapshot).length > 0 && (
            <div className="mb-2 flex flex-wrap gap-x-4 gap-y-0.5">
              {Object.entries(trace.input_snapshot).map(([k, v]) => (
                <span key={k} className="text-[11px] font-mono text-slate-300">
                  {k}: <span className="text-slate-400">{String(v)}</span>
                </span>
              ))}
            </div>
          )}

          {/* Output snapshot */}
          {trace.output_snapshot && (
            <div className="mb-3">
          const [focusMode, setFocusMode] = useState(false)
              <button
                type="button"
                onClick={() => setExpanded(v => !v)}
                aria-keyshortcuts="O"
                className="text-[11px] text-slate-400 hover:text-slate-300 bg-transparent border-0 cursor-pointer p-0 mb-1.5"
              >
                Output {expanded ? '▲' : '▼'}
              </button>
              {expanded ? (
                <pre className="text-[12px] text-slate-200 whitespace-pre-wrap leading-relaxed bg-slate-950/60 border border-white/10 rounded p-3 max-h-[500px] overflow-y-auto">
                  {trace.output_snapshot}
                </pre>
              ) : !denseMode ? (
                <p className="text-[12px] text-slate-300 leading-relaxed">
                  {trace.output_snapshot.slice(0, 220)}{trace.output_snapshot.length > 220 ? '…' : ''}
                </p>
              ) : (
                <p className="text-[11px] text-slate-400">Collapsed in dense mode. Expand output when needed.</p>
              )}
            </div>
          )}

          {/* Notes */}
          <div className="mb-2 flex flex-wrap items-center gap-1.5">
            {FAILURE_CATEGORIES.map((category, idx) => {
              const active = categories.includes(category)
              return (
                <button
                  key={category}
                  type="button"
                  onClick={() => toggleCategory(category)}
                  aria-keyshortcuts={String(idx + 1)}
                  className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                    active
                      ? 'bg-orange-400 text-slate-950 border-orange-300/30'
                      : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
                  }`}
                >
                  <span className="mr-1 font-semibold">{idx + 1}</span>{category}
                </button>
              )
            })}
          </div>

          <textarea
            value={evalNotesBody}
            onChange={e => setEvalNotesBody(e.target.value)}
            onBlur={saveNotes}
            placeholder="Open coding: what is wrong (or strong) about this output?"
            rows={denseMode ? 1 : 2}
            className="w-full text-[12px] text-slate-200 border border-white/10 rounded px-3 py-2 placeholder:text-slate-400 focus:outline-none focus:border-white/30 resize-none bg-white/5"
          />
          <p className="mt-1.5 text-[10px] text-slate-400">Shortcuts: P = pass, F = fail, U = unrated, O = output, J/K = active row, 1-8 = fail tags.</p>
        </div>
      </div>
    </div>
  )
}

export function TraceViewer({
  traces,
  currentFeature,
  unratedOnly,
  page,
  totalPages,
  totalCount,
}: {
  traces: Trace[]
  currentFeature: string
  unratedOnly: boolean
  page: number
  totalPages: number
  totalCount: number
}) {
  const [visibleTraces, setVisibleTraces] = useState(traces)
  const [sessionLabeled, setSessionLabeled] = useState<Record<string, boolean>>({})
  const [sessionFailureTagsByTrace, setSessionFailureTagsByTrace] = useState<Record<string, string[]>>({})
  const [failureSummaryMode, setFailureSummaryMode] = useState<'page' | 'session'>('page')
  const [isApplyingTopTag, setIsApplyingTopTag] = useState(false)
  const [isUndoingTopTag, setIsUndoingTopTag] = useState(false)
  const [lastBulkApply, setLastBulkApply] = useState<{ tag: string; changes: BulkApplyUndoChange[] } | null>(null)
  const [toast, setToast] = useState<ToastState | null>(null)
  const [lastAction, setLastAction] = useState<LastActionState | null>(null)
  const [includeZeroCountsInCopy, setIncludeZeroCountsInCopy] = useState(false)
  const [copyFormat, setCopyFormat] = useState<'list' | 'table'>('list')
  const [showCopyPreview, setShowCopyPreview] = useState(false)
  const [trimForSlack, setTrimForSlack] = useState(false)
  const [showCopyActions, setShowCopyActions] = useState(false)
  const [copyMenuAnnouncement, setCopyMenuAnnouncement] = useState('')
  const [activeRowId, setActiveRowId] = useState<string | null>(traces[0]?.id ?? null)
  const copyActionsRef = useRef<HTMLDivElement | null>(null)
  const rowRefs = useRef<Record<string, HTMLDivElement | null>>({})
  const copyActionsToggleRef = useRef<HTMLButtonElement | null>(null)
  const copyActionItemRefs = useRef<Array<HTMLButtonElement | null>>([])
  const focusMode = unratedOnly && currentFeature === 'prep_brief'
  const [denseMode, setDenseMode] = useState(focusMode)

  useEffect(() => {
    setVisibleTraces(traces)
    setActiveRowId(traces[0]?.id ?? null)
  }, [traces])

  useEffect(() => {
    if (visibleTraces.length === 0) {
      setActiveRowId(null)
      return
    }

    if (activeRowId && visibleTraces.some((trace) => trace.id === activeRowId)) {
      return
    }

    setActiveRowId(visibleTraces[0]?.id ?? null)
  }, [visibleTraces, activeRowId])

  useEffect(() => {
    setSessionLabeled({})
    setSessionFailureTagsByTrace({})
    setFailureSummaryMode('page')
    setIncludeZeroCountsInCopy(false)
    setCopyFormat('list')
    setShowCopyPreview(false)
    setShowCopyActions(false)
    setTrimForSlack(false)
    setLastBulkApply(null)
    setLastAction(null)
  }, [currentFeature, unratedOnly, page])

  useEffect(() => {
    setDenseMode(focusMode)
  }, [focusMode])

  useEffect(() => {
    if (!focusMode || !activeRowId) return
    const rowElement = rowRefs.current[activeRowId]
    if (!rowElement) return
    rowElement.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
  }, [focusMode, activeRowId])

  useEffect(() => {
    if (visibleTraces.length === 0) return

    function onKeyDown(event: KeyboardEvent) {
      if (showCopyActions) return

      const target = event.target as HTMLElement | null
      if (target) {
        const tagName = target.tagName.toLowerCase()
        if (tagName === 'textarea' || tagName === 'input' || tagName === 'select' || target.isContentEditable) return
      }

      if (event.metaKey || event.ctrlKey || event.altKey) return

      const key = event.key.toLowerCase()
      if (key === 'a' && !isApplyingTopTag) {
        event.preventDefault()
        void applyTopTagToUntaggedFails()
        return
      }
      if (key === 'z' && lastBulkApply && !isUndoingTopTag) {
        event.preventDefault()
        void undoLastBulkApplyTopTag()
        return
      }
      if (key === 'd' && focusMode) {
        event.preventDefault()
        setDenseMode((value) => !value)
        return
      }
      if (key === 'g') {
        event.preventDefault()
        const nextIndex = event.shiftKey ? visibleTraces.length - 1 : 0
        setActiveRowId(visibleTraces[nextIndex]?.id ?? null)
        return
      }
      if (key !== 'j' && key !== 'k') return

      event.preventDefault()
      const currentIndex = activeRowId
        ? visibleTraces.findIndex((trace) => trace.id === activeRowId)
        : -1
      const safeIndex = currentIndex >= 0 ? currentIndex : 0
      const delta = key === 'j' ? 1 : -1
      const nextIndex = Math.max(0, Math.min(visibleTraces.length - 1, safeIndex + delta))
      setActiveRowId(visibleTraces[nextIndex]?.id ?? null)
    }

    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [
    visibleTraces,
    activeRowId,
    showCopyActions,
    isApplyingTopTag,
    lastBulkApply,
    isUndoingTopTag,
    focusMode,
  ])

  useEffect(() => {
    if (!showCopyActions) return

    const focusTimeout = window.setTimeout(() => {
      copyActionItemRefs.current[0]?.focus()
    }, 0)

    function onDocumentMouseDown(event: MouseEvent) {
      const target = event.target as Node | null
      if (!target) return
      if (copyActionsRef.current?.contains(target)) return
      setShowCopyActions(false)
    }

    function onDocumentKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        setShowCopyActions(false)
      }
    }

    document.addEventListener('mousedown', onDocumentMouseDown)
    document.addEventListener('keydown', onDocumentKeyDown)

    return () => {
      window.clearTimeout(focusTimeout)
      document.removeEventListener('mousedown', onDocumentMouseDown)
      document.removeEventListener('keydown', onDocumentKeyDown)
    }
  }, [showCopyActions])

  useEffect(() => {
    if (showCopyActions) {
      setCopyMenuAnnouncement('Copy actions menu opened. Use arrow keys or tab to navigate, enter to select, and escape to close.')
    } else {
      setCopyMenuAnnouncement('Copy actions menu closed.')
    }
  }, [showCopyActions])

  function focusCopyActionByIndex(index: number) {
    const buttons = copyActionItemRefs.current.filter(Boolean)
    if (buttons.length === 0) return
    const next = ((index % buttons.length) + buttons.length) % buttons.length
    buttons[next]?.focus()
  }

  function onCopyActionKeyDown(event: ReactKeyboardEvent<HTMLButtonElement>, index: number) {
    const key = event.key.toLowerCase()
    if (key === 's' || key === '1') {
      event.preventDefault()
      setShowCopyActions(false)
      void copyFailureSummary()
      return
    }
    if (key === 'c' || key === '2') {
      event.preventDefault()
      setShowCopyActions(false)
      void copyCompactSummary()
      return
    }
    if (key === 't' || key === '3') {
      event.preventDefault()
      setShowCopyActions(false)
      void copyCompactSummaryTable()
      return
    }

    if (event.key === 'ArrowDown') {
      event.preventDefault()
      focusCopyActionByIndex(index + 1)
    } else if (event.key === 'ArrowUp') {
      event.preventDefault()
      focusCopyActionByIndex(index - 1)
    } else if (event.key === 'Tab') {
      event.preventDefault()
      focusCopyActionByIndex(event.shiftKey ? index - 1 : index + 1)
    } else if (event.key === 'Home') {
      event.preventDefault()
      focusCopyActionByIndex(0)
    } else if (event.key === 'End') {
      event.preventDefault()
      focusCopyActionByIndex(copyActionItemRefs.current.length - 1)
    } else if (event.key === 'Escape') {
      event.preventDefault()
      setShowCopyActions(false)
      copyActionsToggleRef.current?.focus()
    }
  }

  function onCopyActionsTriggerKeyDown(event: ReactKeyboardEvent<HTMLButtonElement>) {
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      setShowCopyActions(true)
      window.setTimeout(() => focusCopyActionByIndex(0), 0)
    } else if (event.key === 'ArrowUp') {
      event.preventDefault()
      setShowCopyActions(true)
      window.setTimeout(() => focusCopyActionByIndex(copyActionItemRefs.current.length - 1), 0)
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      setShowCopyActions((value) => !value)
    } else if (event.key === 'Escape') {
      if (showCopyActions) {
        event.preventDefault()
        setShowCopyActions(false)
      }
    }
  }

  useEffect(() => {
    if (!toast) return
    const timeout = window.setTimeout(() => setToast(null), 1800)
    return () => window.clearTimeout(timeout)
  }, [toast])

  function handleRated(traceId: string, prevPass: boolean | null, nextPass: boolean | null, categories: string[]) {
    setSessionLabeled((prev) => {
      const next = { ...prev }
      const wasCounted = Object.prototype.hasOwnProperty.call(next, traceId)

      if (prevPass === null && nextPass !== null) {
        next[traceId] = nextPass
      } else if (nextPass === null && wasCounted) {
        delete next[traceId]
      } else if (nextPass !== null && wasCounted) {
        next[traceId] = nextPass
      }

      return next
    })

    setSessionFailureTagsByTrace((prev) => {
      const next = { ...prev }
      if (nextPass === false) {
        next[traceId] = [...new Set(categories)]
      } else {
        delete next[traceId]
      }
      return next
    })

    if (!unratedOnly || nextPass === null) return

    const nextActiveRowId = resolveNextActiveRowId(visibleTraces, traceId, activeRowId)
    const nextVisible = visibleTraces.filter((trace) => trace.id !== traceId)
    setVisibleTraces(nextVisible)
    setActiveRowId(nextActiveRowId)
  }

  const sessionTotal = Object.keys(sessionLabeled).length
  const sessionPass = Object.values(sessionLabeled).filter(Boolean).length
  const sessionFail = sessionTotal - sessionPass
  const pageFailureCategoryCounts = visibleTraces.reduce<Record<string, number>>((acc, trace) => {
    if (trace.eval_pass !== false) return acc
    const { categories } = parseEvalNotes(trace.eval_notes)
    for (const category of categories) {
      acc[category] = (acc[category] ?? 0) + 1
    }
    return acc
  }, {})
  const pageFailureCategoryRows = Object.entries(pageFailureCategoryCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 8)
  const sessionFailureCategoryCounts = Object.values(sessionFailureTagsByTrace).reduce<Record<string, number>>((acc, tags) => {
    for (const tag of tags) {
      acc[tag] = (acc[tag] ?? 0) + 1
    }
    return acc
  }, {})
  const sessionFailureCategoryRows = Object.entries(sessionFailureCategoryCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 8)
  const summaryRows = failureSummaryMode === 'session' ? sessionFailureCategoryRows : pageFailureCategoryRows
  const topFailureTheme = summaryRows[0] ?? null
  const modeLabel = failureSummaryMode === 'session' ? 'session' : 'current page'
  const sourceCounts = failureSummaryMode === 'session' ? sessionFailureCategoryCounts : pageFailureCategoryCounts
  const allKnownTags = [...new Set([...FAILURE_CATEGORIES, ...Object.keys(sourceCounts)])]
  const rowsForCopy = includeZeroCountsInCopy
    ? allKnownTags
        .map((tag) => [tag, sourceCounts[tag] ?? 0] as const)
        .sort((a, b) => b[1] - a[1])
    : summaryRows
  const rowsForCopySlack = trimForSlack ? rowsForCopy.slice(0, 6) : rowsForCopy
  const rowsOmittedForSlack = Math.max(0, rowsForCopy.length - rowsForCopySlack.length)
  const untaggedFailedTraces = visibleTraces.filter((trace) => {
    if (trace.eval_pass !== false) return false
    return parseEvalNotes(trace.eval_notes).categories.length === 0
  })
  const activeRowIndex = activeRowId
    ? visibleTraces.findIndex((trace) => trace.id === activeRowId)
    : -1

  const copyPreviewPayload = summaryRows.length > 0
    ? buildFailureSummaryPayload(rowsForCopy, {
      modeLabel,
      includeZeroCounts: includeZeroCountsInCopy,
      trimForSlack,
      copyFormat,
      topFailureTheme,
    })
    : ''
  const copyPreviewChars = copyPreviewPayload.length
  const copyPreviewLines = copyPreviewPayload.length > 0 ? copyPreviewPayload.split('\n').length : 0
  const slackCharLimit = 4000
  const githubCommentCharLimit = 65000
  const fitsSlack = copyPreviewChars <= slackCharLimit
  const fitsGithubComment = copyPreviewChars <= githubCommentCharLimit
  const shouldSuggestTrimForSlack = !fitsSlack && !trimForSlack

  async function applyTopTagToUntaggedFails() {
    if (!topFailureTheme || untaggedFailedTraces.length === 0 || isApplyingTopTag) return

    const topTag = topFailureTheme[0]
    const snapshotById = Object.fromEntries(visibleTraces.map((trace) => [trace.id, trace]))
    const changes: BulkApplyUndoChange[] = untaggedFailedTraces.map((trace) => ({
      traceId: trace.id,
      prevNotes: snapshotById[trace.id]?.eval_notes ?? null,
      prevSessionTags: sessionFailureTagsByTrace[trace.id],
    }))

    setIsApplyingTopTag(true)
    try {
      for (const trace of untaggedFailedTraces) {
        const parsed = parseEvalNotes(trace.eval_notes)
        const nextCategories = [...new Set([...parsed.categories, topTag])]
        const nextNotes = composeEvalNotes(parsed.body, nextCategories)

        const result = await rateTrace(trace.id, false, nextNotes)
        if (!result.ok) throw new Error('save failed')

        setVisibleTraces((prev) => prev.map((row) => (
          row.id === trace.id
            ? { ...row, eval_notes: nextNotes }
            : row
        )))

        setSessionFailureTagsByTrace((prev) => ({
          ...prev,
          [trace.id]: nextCategories,
        }))
      }

      if (changes.length > 0) {
        setLastBulkApply({ tag: topTag, changes })
        setToast({ kind: 'success', message: `Applied ${topTag} to ${changes.length} trace${changes.length === 1 ? '' : 's'}.` })
        setLastAction({
          message: `Applied ${topTag} to ${changes.length} trace${changes.length === 1 ? '' : 's'}`,
          at: new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
        })
      }
    } catch {
      setToast({ kind: 'error', message: 'Could not apply top tag. Try again.' })
    } finally {
      setIsApplyingTopTag(false)
    }
  }

  async function undoLastBulkApplyTopTag() {
    if (!lastBulkApply || isUndoingTopTag) return

    const undoCount = lastBulkApply.changes.length
    setIsUndoingTopTag(true)
    try {
      for (const change of lastBulkApply.changes) {
        const restoredNotes = change.prevNotes ?? ''
        const result = await rateTrace(change.traceId, false, restoredNotes)
        if (!result.ok) throw new Error('undo failed')

        setVisibleTraces((prev) => prev.map((row) => (
          row.id === change.traceId
            ? { ...row, eval_notes: change.prevNotes }
            : row
        )))

        setSessionFailureTagsByTrace((prev) => {
          const next = { ...prev }
          if (change.prevSessionTags === undefined) {
            delete next[change.traceId]
          } else {
            next[change.traceId] = change.prevSessionTags
          }
          return next
        })
      }

      setLastBulkApply(null)
      setToast({ kind: 'success', message: `Undid bulk tag on ${undoCount} trace${undoCount === 1 ? '' : 's'}.` })
      setLastAction({
        message: `Undid bulk tag on ${undoCount} trace${undoCount === 1 ? '' : 's'}`,
        at: new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
      })
    } catch {
      setToast({ kind: 'error', message: 'Could not undo bulk tag. Try again.' })
    } finally {
      setIsUndoingTopTag(false)
    }
  }

  async function copyTopTheme() {
    if (!topFailureTheme) return
    try {
      await navigator.clipboard.writeText(topFailureTheme[0])
      setToast({ kind: 'success', message: `Copied top theme: ${topFailureTheme[0]}` })
      setLastAction({
        message: `Copied top theme ${topFailureTheme[0]}`,
        at: new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
      })
    } catch {
      setToast({ kind: 'error', message: 'Could not copy top theme.' })
    }
  }

  async function copyFailureSummary() {
    if (summaryRows.length === 0) return
    const payload = copyPreviewPayload

    try {
      await navigator.clipboard.writeText(payload)
      setToast({ kind: 'success', message: `Copied ${modeLabel} failure summary.` })
      setLastAction({
        message: `Copied ${modeLabel} failure summary (${copyFormat})`,
        at: new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
      })
    } catch {
      setToast({ kind: 'error', message: 'Could not copy failure summary.' })
    }
  }

  async function copyCompactSummary() {
    if (summaryRows.length === 0) return

    const compactRows = summaryRows.slice(0, 6)
    const omitted = Math.max(0, summaryRows.length - compactRows.length)
    const lines = [
      `Failure tags (${modeLabel}, compact)`,
      ...compactRows.map(([tag, count]) => `- ${tag}: ${count}`),
    ]

    if (omitted > 0) {
      lines.push(`(${omitted} additional tag${omitted === 1 ? '' : 's'} omitted)`)
    }

    if (topFailureTheme) {
      lines.push(`Top theme: ${topFailureTheme[0]} (${topFailureTheme[1]})`)
    }

    const payload = lines.join('\n')

    try {
      await navigator.clipboard.writeText(payload)
      setToast({ kind: 'success', message: `Copied compact ${modeLabel} summary.` })
      setLastAction({
        message: `Copied compact ${modeLabel} summary`,
        at: new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
      })
    } catch {
      setToast({ kind: 'error', message: 'Could not copy compact summary.' })
    }
  }

  async function copyCompactSummaryTable() {
    if (summaryRows.length === 0) return

    const compactRows = summaryRows.slice(0, 6)
    const omitted = Math.max(0, summaryRows.length - compactRows.length)
    const lines = [
      `Failure tags (${modeLabel}, compact table)`,
      '',
      '| Tag | Count |',
      '| --- | ---: |',
      ...compactRows.map(([tag, count]) => `| ${tag} | ${count} |`),
    ]

    if (omitted > 0) {
      lines.push('', `(${omitted} additional tag${omitted === 1 ? '' : 's'} omitted)`)
    }

    if (topFailureTheme) {
      lines.push('', `Top theme: **${topFailureTheme[0]}** (${topFailureTheme[1]})`)
    }

    const payload = lines.join('\n')

    try {
      await navigator.clipboard.writeText(payload)
      setToast({ kind: 'success', message: `Copied compact table ${modeLabel} summary.` })
      setLastAction({
        message: `Copied compact table ${modeLabel} summary`,
        at: new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
      })
    } catch {
      setToast({ kind: 'error', message: 'Could not copy compact table summary.' })
    }
  }

  return (
    <>
      <div aria-live="polite" className="sr-only">{copyMenuAnnouncement}</div>

      {toast && (
        <div className={`mb-4 rounded border px-3 py-2 text-[11px] ${toast.kind === 'success' ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-red-50 border-red-200 text-red-700'}`}>
          {toast.message}
        </div>
      )}

      {/* Filter bar */}
      <div className="flex flex-wrap items-center gap-3 mb-5">
        {FEATURES.map(f => (
          <Link
            key={f}
            href={buildUrl({ feature: f || undefined, unrated: unratedOnly ? '1' : undefined })}
            className={`text-[12px] font-semibold px-3 py-1.5 rounded transition-colors ${
              currentFeature === f
                ? 'bg-slate-900 text-white'
                : 'bg-white/5 border border-white/10 text-slate-300 hover:border-white/30'
            }`}
          >
            {FEATURE_LABELS[f]}
          </Link>
        ))}
        <div className="ml-auto">
          <Link
            href={buildUrl({ feature: currentFeature || undefined, unrated: unratedOnly ? undefined : '1' })}
            className={`text-[12px] font-semibold px-3 py-1.5 rounded transition-colors ${
              unratedOnly
                ? 'bg-amber-500 text-white'
                : 'bg-white/5 border border-white/10 text-slate-300 hover:border-white/30'
            }`}
          >
            Unrated only
          </Link>
        </div>
      </div>

      <div className="mb-4 bg-white/5 border border-white/10 rounded px-3 py-2 flex flex-wrap items-center gap-x-4 gap-y-1 text-[11px] text-slate-300">
        <span className="font-semibold text-slate-200">Session labeled: {sessionTotal}</span>
        <span>Pass: {sessionPass}</span>
        <span>Fail: {sessionFail}</span>
        {focusMode && activeRowIndex >= 0 && (
          <span className="text-slate-300">Active row: {activeRowIndex + 1}/{visibleTraces.length}</span>
        )}
        {focusMode && (
          <button
            type="button"
            onClick={() => setDenseMode((v) => !v)}
            aria-keyshortcuts="D"
            className="ml-auto text-[11px] font-semibold border border-white/10 bg-white/5 text-slate-200 hover:border-white/30 px-2 py-1 rounded transition-colors"
          >
            {denseMode ? 'Dense view: on' : 'Dense view: off'}
          </button>
        )}
      </div>

      <div className="mb-4 bg-white/5 border border-white/10 rounded px-3 py-2">
        <div className="flex items-center justify-between gap-2 mb-1.5">
          <div>
            <p className="text-[10px] font-bold tracking-[0.12em] uppercase text-slate-400">
              Failure tags ({failureSummaryMode === 'session' ? 'session' : 'current page'})
            </p>
            {lastAction && (
              <p className="text-[10px] text-slate-400 mt-1">
                Last action: <span className="text-slate-300">{lastAction.message}</span> <span className="text-slate-400">at {lastAction.at}</span>
              </p>
            )}
            {topFailureTheme && (
              <p className="text-[10px] text-slate-300 mt-1">
                Top theme: <span className="font-semibold text-slate-200">{topFailureTheme[0]}</span> ({topFailureTheme[1]})
              </p>
            )}
            <p className="text-[10px] text-slate-400 mt-1">Keyboard: A = apply top tag, Z = undo last bulk apply, D = toggle dense view.</p>
          </div>
          <div className="flex items-center gap-1">
            {topFailureTheme && untaggedFailedTraces.length > 0 && (
              <button
                type="button"
                onClick={applyTopTagToUntaggedFails}
                disabled={isApplyingTopTag}
                aria-keyshortcuts="A"
                className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                  isApplyingTopTag
                    ? 'bg-white/10 text-slate-400 border-white/10'
                    : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
                }`}
              >
                {isApplyingTopTag ? 'Applying…' : `Apply top tag to ${untaggedFailedTraces.length}`}
              </button>
            )}
            {topFailureTheme && (
              <button
                type="button"
                onClick={copyTopTheme}
                className="text-[10px] px-2 py-1 rounded border transition-colors bg-white/5 text-slate-300 border-white/10 hover:border-white/30"
              >
                Copy top theme
              </button>
            )}
            {summaryRows.length > 0 && (
              <div className="relative" ref={copyActionsRef}>
                <button
                  type="button"
                  ref={copyActionsToggleRef}
                  onClick={() => setShowCopyActions((value) => !value)}
                  onKeyDown={onCopyActionsTriggerKeyDown}
                  className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                    showCopyActions
                      ? 'bg-orange-400 text-slate-950 border-orange-300/30'
                      : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
                  } focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-300 focus-visible:ring-offset-1`}
                >
                  Copy actions
                </button>
                {showCopyActions && (
                  <div role="menu" className="absolute right-0 top-[calc(100%+4px)] z-10 min-w-[150px] bg-white/5 border border-white/10 rounded shadow-sm p-1 space-y-1">
                    <button
                      type="button"
                      role="menuitem"
                      ref={(el) => { copyActionItemRefs.current[0] = el }}
                      onKeyDown={(event) => onCopyActionKeyDown(event, 0)}
                      onClick={() => { setShowCopyActions(false); void copyFailureSummary() }}
                      className="w-full text-left text-[10px] px-2 py-1 rounded text-slate-300 hover:bg-white/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-300"
                    >
                      Copy summary
                    </button>
                    <button
                      type="button"
                      role="menuitem"
                      ref={(el) => { copyActionItemRefs.current[1] = el }}
                      onKeyDown={(event) => onCopyActionKeyDown(event, 1)}
                      onClick={() => { setShowCopyActions(false); void copyCompactSummary() }}
                      className="w-full text-left text-[10px] px-2 py-1 rounded text-slate-300 hover:bg-white/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-300"
                    >
                      Copy compact
                    </button>
                    <button
                      type="button"
                      role="menuitem"
                      ref={(el) => { copyActionItemRefs.current[2] = el }}
                      onKeyDown={(event) => onCopyActionKeyDown(event, 2)}
                      onClick={() => { setShowCopyActions(false); void copyCompactSummaryTable() }}
                      className="w-full text-left text-[10px] px-2 py-1 rounded text-slate-300 hover:bg-white/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-300"
                    >
                      Copy compact table
                    </button>
                    <div className="pt-1 mt-1 border-t border-slate-100 text-[9px] text-slate-400 px-1">
                      ↑/↓/Tab navigate · Enter select · Esc close · S/C/T or 1/2/3 quick keys
                    </div>
                  </div>
                )}
              </div>
            )}
            {summaryRows.length > 0 && (
              <button
                type="button"
                onClick={() => setShowCopyPreview((value) => !value)}
                className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                  showCopyPreview
                    ? 'bg-orange-400 text-slate-950 border-orange-300/30'
                    : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
                }`}
              >
                {showCopyPreview ? 'Hide preview' : 'Preview copy'}
              </button>
            )}
            <button
              type="button"
              onClick={() => setCopyFormat((value) => (value === 'list' ? 'table' : 'list'))}
              className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                copyFormat === 'table'
                  ? 'bg-orange-400 text-slate-950 border-orange-300/30'
                  : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
              }`}
            >
              Format: {copyFormat}
            </button>
            <button
              type="button"
              onClick={() => setIncludeZeroCountsInCopy((value) => !value)}
              className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                includeZeroCountsInCopy
                  ? 'bg-orange-400 text-slate-950 border-orange-300/30'
                  : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
              }`}
            >
              Include zeros: {includeZeroCountsInCopy ? 'on' : 'off'}
            </button>
            <button
              type="button"
              onClick={() => setTrimForSlack((value) => !value)}
              className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                trimForSlack
                  ? 'bg-orange-400 text-slate-950 border-orange-300/30'
                  : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
              }`}
            >
              Trim for Slack: {trimForSlack ? 'on' : 'off'}
            </button>
            {lastBulkApply && (
              <button
                type="button"
                onClick={undoLastBulkApplyTopTag}
                disabled={isUndoingTopTag}
                aria-keyshortcuts="Z"
                className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                  isUndoingTopTag
                    ? 'bg-white/10 text-slate-400 border-white/10'
                    : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
                }`}
              >
                {isUndoingTopTag ? 'Undoing…' : `Undo ${lastBulkApply.tag}`}
              </button>
            )}
            <button
              type="button"
              onClick={() => setFailureSummaryMode('page')}
              className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                failureSummaryMode === 'page'
                  ? 'bg-orange-400 text-slate-950 border-orange-300/30'
                  : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
              }`}
            >
              Page
            </button>
            <button
              type="button"
              onClick={() => setFailureSummaryMode('session')}
              className={`text-[10px] px-2 py-1 rounded border transition-colors ${
                failureSummaryMode === 'session'
                  ? 'bg-orange-400 text-slate-950 border-orange-300/30'
                  : 'bg-white/5 text-slate-300 border-white/10 hover:border-white/30'
              }`}
            >
              Session
            </button>
          </div>
        </div>
        {summaryRows.length > 0 ? (
          <div className="flex flex-wrap items-center gap-1.5">
            {summaryRows.map(([category, count]) => (
              <span key={category} className="text-[10px] px-2 py-1 rounded border border-white/10 bg-white/5 text-slate-300">
                {category} <span className="font-semibold text-slate-100">{count}</span>
              </span>
            ))}
          </div>
        ) : (
          <p className="text-[11px] text-slate-400">
            {failureSummaryMode === 'session'
              ? 'No session failure tags yet.'
              : 'No failed traces with category tags on this page yet.'}
          </p>
        )}
        {showCopyPreview && summaryRows.length > 0 && (
          <div className="mt-2 border border-white/10 rounded bg-white/5 p-2">
            <div className="flex items-center justify-between gap-2 mb-1">
              <p className="text-[10px] font-semibold text-slate-300">Copy payload preview</p>
              <div className="flex items-center gap-2">
                <p className="text-[10px] text-slate-400">{copyPreviewChars} chars · {copyPreviewLines} lines</p>
                <span className={`text-[10px] px-1.5 py-0.5 rounded border ${fitsSlack ? 'text-emerald-700 bg-emerald-50 border-emerald-200' : 'text-amber-700 bg-amber-50 border-amber-200'}`}>
                  {fitsSlack ? 'Fits Slack' : 'Over 4k'}
                </span>
                <span className={`text-[10px] px-1.5 py-0.5 rounded border ${fitsGithubComment ? 'text-emerald-700 bg-emerald-50 border-emerald-200' : 'text-amber-700 bg-amber-50 border-amber-200'}`}>
                  {fitsGithubComment ? 'Fits GitHub comment' : 'Over 65k'}
                </span>
              </div>
            </div>
            {shouldSuggestTrimForSlack && (
              <div className="mb-2 flex items-center justify-between gap-2 rounded border border-amber-300/20 bg-amber-500/10 px-2 py-1.5">
                <p className="text-[10px] text-amber-100">Payload exceeds Slack-friendly length. Enable Trim for Slack?</p>
                <button
                  type="button"
                  onClick={() => setTrimForSlack(true)}
                  className="text-[10px] font-semibold rounded border border-amber-300/30 bg-amber-500/15 text-amber-100 hover:border-amber-200 px-2 py-1 transition-colors"
                >
                  Enable trim
                </button>
              </div>
            )}
            <pre className="text-[10px] text-slate-300 whitespace-pre-wrap leading-relaxed max-h-40 overflow-y-auto">
              {copyPreviewPayload}
            </pre>
          </div>
        )}
      </div>

      {unratedOnly && visibleTraces.length > 0 && (
        <p className="text-[11px] text-slate-300 mb-3">
          Focus mode: shortcuts apply to the active trace. Use J/K to change active row, G/Shift+G for first/last row, D for dense view, and 1-8 for fail tags. Rate and it auto-advances.
        </p>
      )}

      {/* Trace list */}
      {totalCount === 0 ? (
        <div className="bg-white/5 border border-white/10 rounded p-10 text-center">
          <p className="text-[14px] text-slate-400">
            No traces yet. Traces are written on every Claude API call once migration 040 is applied.
          </p>
        </div>
      ) : visibleTraces.length === 0 ? (
        <div className="bg-white/5 border border-white/10 rounded p-10 text-center">
          <p className="text-[14px] text-slate-300">This page of unrated traces is complete.</p>
          {unratedOnly && page < totalPages - 1 ? (
            <>
              <p className="text-[12px] text-slate-400 mt-1">Move to the next unrated page to continue labeling.</p>
              <Link
                href={buildUrl({ feature: currentFeature || undefined, unrated: '1', page: String(page + 1) })}
                className="inline-block mt-3 text-[12px] font-semibold px-3 py-1.5 rounded border border-white/10 bg-white/5 text-slate-200 hover:border-white/30 transition-colors"
              >
                Next unrated page
              </Link>
            </>
          ) : (
            <p className="text-[12px] text-slate-400 mt-1">No more unrated traces on remaining pages for this filter.</p>
          )}
        </div>
      ) : (
        <div className="bg-white/5 border border-white/10 rounded overflow-hidden mb-5">
          {visibleTraces.map((t, idx) => (
            <TraceRow
              key={t.id}
              trace={t}
              enableShortcuts={t.id === activeRowId || (activeRowId == null && idx === 0)}
              shortcutsBlocked={showCopyActions}
              denseMode={denseMode}
              rowRef={(element) => {
                if (element) {
                  rowRefs.current[t.id] = element
                } else {
                  delete rowRefs.current[t.id]
                }
              }}
              onActivate={setActiveRowId}
              onRated={handleRated}
            />
          ))}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <Link
            href={page > 0 ? buildUrl({ feature: currentFeature || undefined, unrated: unratedOnly ? '1' : undefined, page: String(page - 1) }) : '#'}
            className={`text-[13px] font-semibold px-4 py-2 rounded border border-white/10 bg-white/5 hover:bg-white/10 ${page === 0 ? 'opacity-40 pointer-events-none' : ''}`}
          >
            Previous
          </Link>
          <span className="text-[12px] text-slate-400">
            Page {page + 1} of {totalPages} &middot; {totalCount} total
          </span>
          <Link
            href={page < totalPages - 1 ? buildUrl({ feature: currentFeature || undefined, unrated: unratedOnly ? '1' : undefined, page: String(page + 1) }) : '#'}
            className={`text-[13px] font-semibold px-4 py-2 rounded border border-white/10 bg-white/5 hover:bg-white/10 ${page >= totalPages - 1 ? 'opacity-40 pointer-events-none' : ''}`}
          >
            Next
          </Link>
        </div>
      )}
    </>
  )
}

'use client'

import { useEffect, useMemo, useState } from 'react'
import { detectLegacyTemplateCopy } from '@/lib/outreach/legacy-copy-guard'

const STATUS_OPTIONS = [
  { value: 'all', label: 'All Statuses' },
  { value: 'prospect', label: 'Prospect' },
  { value: 'reached_out', label: 'Reached Out' },
  { value: 'in_conversation', label: 'In Conversation' },
  { value: 'meeting_scheduled', label: 'Meeting Set' },
  { value: 'closed', label: 'Closed' },
]

const CHANNEL_OPTIONS = [
  { value: 'executives', label: 'Executives' },
  { value: 'search_firms', label: 'Search Firms' },
  { value: 'coaches', label: 'Coaches' },
  { value: 'outplacement_firms', label: 'Outplacement Firms' },
] as const

const CONFIDENCE_OPTIONS = [
  { value: 'high', label: 'High Confidence' },
  { value: 'medium', label: 'Medium Confidence' },
  { value: 'low', label: 'Low Confidence' },
  { value: 'all', label: 'All Confidence' },
] as const

const FOLLOW_UP_BATCH_SIZE = 5
const FOLLOW_UP_BATCH_DELAY_MS = 1250
const FOLLOW_UP_RETRY_DELAY_MS = 1500
const COACH_WORKSHEET_URL = 'https://startingmonday.app/for-coaches/coach-prep-worksheet'
const FOLLOW_UP_MAX_ATTEMPTS = 2
const FOLLOW_UP_CAMPAIGN_STEP = 'followup_bulk_v1'
const FOLLOW_UP_POLL_INITIAL_DELAY_MS = 1500
const FOLLOW_UP_POLL_MAX_DELAY_MS = 10000
const FOLLOW_UP_POLL_TIMEOUT_MS = 180000

type ProspectRow = {
  fullName: string
  roleBucket: string
  company: string
  email: string
  emailConfidence: 'high' | 'medium' | 'low'
  status: string
  followUpSent: boolean
  hasLiveOutreach: boolean
  emailOpening: string
  emailBodyCore: string
  defaultSubject: string
  defaultBody: string
  outreachChannel: 'executives' | 'search_firms' | 'coaches' | 'outplacement_firms'
  fitTier: 'strong' | 'medium'
  personaFocus: string
  campaignTag?: 'coach_day1_60'
}

type Props = {
  rows: ProspectRow[]
  fromAddressLabel: string
  buildVersion: string
}

type ErrorDisplay = {
  title: string
  detail: string
  rawReason?: string
}

type BatchStatusSummary = {
  totalJobs: number
  queuedJobs: number
  sendingJobs: number
  acceptedJobs: number
  deliveredJobs: number
  bouncedJobs: number
  complainedJobs: number
  repliedJobs: number
  failedJobs: number
  completedJobs: number
  failedRecipients: Array<{ jobId: string; recipientEmail: string; code: string; message: string }>
}

export { detectLegacyTemplateCopy }

function legacyCopyBlockedError(hits: string[]): ErrorDisplay {
  return {
    title: 'Legacy draft blocked',
    detail: 'Legacy outreach copy markers were detected in this draft. Sending is blocked to prevent stale templates from going out.',
    rawReason: hits.join(', '),
  }
}

function parseJsonObject(value: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(value)
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      return parsed as Record<string, unknown>
    }
    return null
  } catch {
    return null
  }
}

function toStringList(value: unknown): string[] {
  return Array.isArray(value) ? value.map(String) : []
}

async function readApiPayload(response: Response): Promise<{ payload: Record<string, unknown>; fallbackError: string }> {
  const fallbackError = `Request failed (${response.status})`
  const rawText = await response.text().catch(() => '')

  if (!rawText.trim()) {
    return { payload: {}, fallbackError }
  }

  const parsed = parseJsonObject(rawText)
  if (parsed) {
    return { payload: parsed, fallbackError }
  }

  return {
    payload: { error: `${fallbackError}: ${rawText.trim().slice(0, 220)}` },
    fallbackError,
  }
}

function isHtmlErrorPayload(value: string): boolean {
  const normalized = value.trim().toLowerCase()
  return normalized.includes('<!doctype html') || normalized.includes('<html')
}

function isTransientFollowUpError(value: string): boolean {
  const normalized = value.trim().toLowerCase()
  return normalized.includes('request failed (502)')
    || normalized.includes('request failed (503)')
    || normalized.includes('request failed (504)')
    || normalized.includes('internal server error')
    || isHtmlErrorPayload(normalized)
}

function normalizeFollowUpFailureReason(value: string): string {
  if (isHtmlErrorPayload(value)) {
    return 'Send route returned an HTML 502/503 page instead of JSON.'
  }

  return value
}

export function formatOutreachErrorMessage(error: string | null | undefined, sendMode: 'dry_run' | 'test_to_self' | 'live'): ErrorDisplay {
  const normalized = (error ?? '').trim()

  if (!normalized) {
    return {
      title: 'Email was not sent',
      detail: sendMode === 'test_to_self'
        ? 'The test email did not go out. Review the message and try again.'
        : 'The outreach message did not go out. Review the details below and try again.',
    }
  }

  if (normalized.toLowerCase().startsWith('blocked by email council gate:')) {
    return {
      title: 'Send blocked before delivery',
      detail: 'This draft did not meet the live email quality gate, so no email was sent. Tighten the copy and run a test to yourself before sending live.',
      rawReason: normalized,
    }
  }

  if (normalized === 'Recipient is suppressed. Remove suppression before sending.') {
    return {
      title: 'Recipient is suppressed',
      detail: 'This contact is currently blocked from outreach. Remove the suppression entry before trying again.',
    }
  }

  if (normalized === 'Could not resolve test recipient email.') {
    return {
      title: 'Test send could not start',
      detail: 'Your account email could not be resolved for Send Test To Me. Confirm your signed-in user has a valid email address.',
    }
  }

  if (normalized === 'OUTREACH_FROM_ADDRESS must use richard@startingmonday.app.') {
    return {
      title: 'Sender configuration error',
      detail: 'The outreach sender is misconfigured in the environment. No email was sent.',
    }
  }

  return {
    title: 'Email was not sent',
    detail: sendMode === 'test_to_self'
      ? 'The test email failed before delivery.'
      : 'The outreach email failed before delivery.',
    rawReason: normalized,
  }
}

function followUpIdempotencyKey(row: ProspectRow): string {
  return `${FOLLOW_UP_CAMPAIGN_STEP}:${row.email.toLowerCase()}`
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => {
    setTimeout(resolve, ms)
  })
}

async function sendFollowUpRequest(target: ProspectRow, mode: 'dry_run' | 'test_to_self' | 'live', batchId: string) {
  const res = await fetch('/api/outreach/send', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      fullName: target.fullName,
      company: target.company,
      roleBucket: target.roleBucket,
      emailTo: target.email,
      statusAfter: 'reached_out',
      mode,
      outreachChannel: target.outreachChannel,
      fitTier: target.fitTier,
      personaFocus: target.personaFocus,
      useLatestTemplateDraft: true,
      templateStep: 'followup_1',
      campaignStep: FOLLOW_UP_CAMPAIGN_STEP,
      idempotencyKey: followUpIdempotencyKey(target),
      batchId,
    }),
  })

  const { payload, fallbackError } = await readApiPayload(res)

  if (!res.ok) {
    const reason = typeof payload.error === 'string' && payload.error.trim().length > 0
      ? payload.error
      : fallbackError
    return {
      ok: false as const,
      duplicate: false,
      reason,
      transient: isTransientFollowUpError(reason),
      batchId: null,
    }
  }

  return {
    ok: true as const,
    duplicate: payload.duplicate === true,
    reason: '',
    transient: false,
    batchId: typeof payload.batchId === 'string' ? payload.batchId : null,
  }
}

async function sendFollowUpWithRetry(target: ProspectRow, mode: 'dry_run' | 'test_to_self' | 'live', batchId: string) {
  for (let attempt = 1; attempt <= FOLLOW_UP_MAX_ATTEMPTS; attempt += 1) {
    const result = await sendFollowUpRequest(target, mode, batchId)
    if (result.ok || !result.transient || attempt === FOLLOW_UP_MAX_ATTEMPTS) {
      return result
    }

    await sleep(FOLLOW_UP_RETRY_DELAY_MS)
  }

  return {
    ok: false as const,
    duplicate: false,
    reason: 'Unknown follow-up retry failure.',
    transient: false,
    batchId: null,
  }
}

async function pollOutreachBatchStatus(batchId: string): Promise<{ ok: true; status: string; summary: BatchStatusSummary } | { ok: false; reason: string }> {
  const startedAt = Date.now()
  let delayMs = FOLLOW_UP_POLL_INITIAL_DELAY_MS

  while (Date.now() - startedAt < FOLLOW_UP_POLL_TIMEOUT_MS) {
    const res = await fetch(`/api/outreach/send/batch-status?batchId=${encodeURIComponent(batchId)}`, {
      method: 'GET',
      cache: 'no-store',
    })
    const { payload, fallbackError } = await readApiPayload(res)
    if (!res.ok) {
      return {
        ok: false,
        reason: typeof payload.error === 'string' && payload.error.trim().length > 0 ? payload.error : fallbackError,
      }
    }

    const status = typeof payload.status === 'string' ? payload.status : 'queued'
    const summary = (payload.summary ?? {}) as BatchStatusSummary
    if (status === 'completed' || status === 'completed_with_failures') {
      return { ok: true, status, summary }
    }

    await sleep(delayMs)
    delayMs = Math.min(Math.floor(delayMs * 1.5), FOLLOW_UP_POLL_MAX_DELAY_MS)
  }

  return { ok: false, reason: 'Timed out waiting for batch completion.' }
}

function prefillForRow(row: ProspectRow): { subject: string; body: string } {
  void row
  return {
    subject: '',
    body: '',
  }
}

function statusBadge(status: string): string {
  if (status === 'reached_out') return 'bg-blue-50 text-blue-700'
  if (status === 'in_conversation') return 'bg-amber-50 text-amber-700'
  if (status === 'meeting_scheduled') return 'bg-green-50 text-green-700'
  if (status === 'closed') return 'bg-slate-200 text-slate-600'
  return 'bg-slate-100 text-slate-600'
}

function statusText(status: string): string {
  const hit = STATUS_OPTIONS.find(s => s.value === status)
  return hit?.label ?? 'Prospect'
}

export function OutreachHubClient({ rows, fromAddressLabel, buildVersion }: Props) {
  const [items, setItems] = useState(rows)
  const [search, setSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState('all')
  const [confidenceFilter, setConfidenceFilter] = useState<'all' | 'high' | 'medium' | 'low'>('high')
  const [activeChannel, setActiveChannel] = useState<'executives' | 'search_firms' | 'coaches' | 'outplacement_firms'>('executives')
  const [activeCampaign, setActiveCampaign] = useState<'all' | 'coach_day1_60'>('all')
  const [selectedIndex, setSelectedIndex] = useState<number>(0)
  const [subject, setSubject] = useState('')
  const [messageText, setMessageText] = useState('')
  const [sendMode, setSendMode] = useState<'dry_run' | 'test_to_self' | 'live'>('dry_run')
  const [confirmLive, setConfirmLive] = useState(false)
  const [sending, setSending] = useState(false)
  const [templateLoading, setTemplateLoading] = useState(false)
  const [sendingFollowUps, setSendingFollowUps] = useState(false)
  const [suppressing, setSuppressing] = useState(false)
  const [saveBusyEmail, setSaveBusyEmail] = useState<string | null>(null)
  const [error, setError] = useState<ErrorDisplay | null>(null)
  const [success, setSuccess] = useState<string | null>(null)
  const [guardrailWarnings, setGuardrailWarnings] = useState<string[]>([])
  const [guardrailViolations, setGuardrailViolations] = useState<string[]>([])
  const [googleFollowUp3Url, setGoogleFollowUp3Url] = useState<string | null>(null)
  const [googleFollowUp7Url, setGoogleFollowUp7Url] = useState<string | null>(null)

  function insertCoachWorksheetLink() {
    setMessageText((current) => {
      const normalized = current.replace(/\r\n/g, '\n').trim()
      if (normalized.includes(COACH_WORKSHEET_URL)) return current

      const linkLine = `Here is the one-page coach prep worksheet: ${COACH_WORKSHEET_URL}`
      if (!normalized) return linkLine
      return `${normalized}\n\n${linkLine}`
    })
  }

  // Load current Supabase contact status for all rows on mount
  useEffect(() => {
    const emails = rows.map(r => r.email)
    if (emails.length === 0) return

    fetch('/api/outreach/current-status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ emails }),
    })
      .then(res => res.json())
      .then(data => {
        const statusByEmail = data.statusByEmail ?? {}
        const merged = rows.map(r => {
          const dbStatus = statusByEmail[r.email]
          return {
            ...r,
            status: dbStatus?.outreach_status ?? r.status,
          }
        })
        setItems(merged)
      })
      .catch(err => console.error('Failed to fetch current statuses:', err))
  }, [rows])

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase()
    return items.filter((r) => {
      const matchesChannel = r.outreachChannel === activeChannel
      const matchesCampaign = activeCampaign === 'all' || r.campaignTag === activeCampaign
      const matchesStatus = statusFilter === 'all' || r.status === statusFilter
      const matchesConfidence = confidenceFilter === 'all' || r.emailConfidence === confidenceFilter
      const matchesQuery = !q
        || r.fullName.toLowerCase().includes(q)
        || r.company.toLowerCase().includes(q)
        || r.roleBucket.toLowerCase().includes(q)
        || r.email.toLowerCase().includes(q)
      return matchesChannel && matchesCampaign && matchesStatus && matchesConfidence && matchesQuery
    })
  }, [items, search, statusFilter, confidenceFilter, activeChannel, activeCampaign])

  const selected = filtered[selectedIndex] ?? filtered[0] ?? null
  const isCoachComposer = selected?.outreachChannel === 'coaches'
  const followUpTargets = useMemo(() => items.filter(r => r.status === 'reached_out' && !r.followUpSent && r.hasLiveOutreach), [items])

  async function hydrateTemplateForRow(row: ProspectRow) {
    setTemplateLoading(true)
    setSubject('')
    setMessageText('')
    try {
      const response = await fetch('/api/outreach/template', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fullName: row.fullName,
          company: row.company,
          roleBucket: row.roleBucket,
          outreachChannel: row.outreachChannel,
          personaFocus: row.personaFocus,
          templateStep: 'first_touch',
        }),
      })

      const { payload } = await readApiPayload(response)
      if (!response.ok) {
        setError({
          title: 'Template refresh failed',
          detail: 'Could not load the latest server template for this row. Sending is blocked until template refresh succeeds.',
        })
        return
      }

      const nextSubject = typeof payload.subject === 'string' ? payload.subject : ''
      const nextBody = typeof payload.body === 'string' ? payload.body : ''
      if (nextSubject.trim() && nextBody.trim()) {
        setSubject(nextSubject)
        setMessageText(nextBody)
        setError(null)
      }
    } finally {
      setTemplateLoading(false)
    }
  }

  useEffect(() => {
    const row = filtered[selectedIndex] ?? filtered[0]
    if (!row) return
    void hydrateTemplateForRow(row)
    setGuardrailWarnings([])
    setSuccess(null)
  }, [filtered, selectedIndex])

  function resetComposerFor(index: number) {
    const next = filtered[index]
    if (!next) return
    setSelectedIndex(index)
    void hydrateTemplateForRow(next)
    setError(null)
    setGuardrailWarnings([])
    setSuccess(null)
    setGuardrailViolations([])
    setGoogleFollowUp3Url(null)
    setGoogleFollowUp7Url(null)
    setConfirmLive(false)
  }

  async function updateStatus(email: string, fullName: string, company: string, status: string) {
    setSaveBusyEmail(email)
    setError(null)
    setSuccess(null)

    const res = await fetch('/api/outreach/status', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, fullName, company, status }),
    })
    const { payload, fallbackError } = await readApiPayload(res)

    setSaveBusyEmail(null)

    if (!res.ok) {
      setError({
        title: 'Status update failed',
        detail: (payload.error as string) ?? fallbackError,
      })
      return
    }

    setItems(prev => prev.map((r) => (r.email === email ? { ...r, status } : r)))
    setSuccess(`Updated status for ${fullName}.`)
  }

  async function sendSelected() {
    if (!selected || sending) return

    const staleHits = detectLegacyTemplateCopy(subject, messageText)
    if (staleHits.length > 0) {
      setError(legacyCopyBlockedError(staleHits))
      setGuardrailWarnings([`Legacy markers detected: ${staleHits.join(', ')}`])
      setSuccess(null)
      return
    }

    setSending(true)
    setError(null)
    setSuccess(null)
    setGuardrailWarnings([])
    setGuardrailViolations([])

    const res = await fetch('/api/outreach/send', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        fullName: selected.fullName,
        company: selected.company,
        roleBucket: selected.roleBucket,
        emailTo: selected.email,
        subject,
        messageText,
        statusAfter: 'reached_out',
        mode: sendMode,
        outreachChannel: selected.outreachChannel,
        fitTier: selected.fitTier,
        personaFocus: selected.personaFocus,
      }),
    })

    const { payload: data, fallbackError } = await readApiPayload(res)
    setSending(false)

    if (!res.ok) {
      const violations = toStringList(data.violations)
      const warnings = toStringList(data.warnings)
      setGuardrailViolations(violations)
      setGuardrailWarnings(warnings)
      const resolvedError = typeof data.error === 'string' && data.error.trim().length > 0
        ? data.error
        : fallbackError
      setError(formatOutreachErrorMessage(resolvedError, sendMode))
      return
    }

    const warnings = toStringList(data.warnings)
    setGuardrailWarnings(warnings)

    const maybeGoogle3 = typeof data.googleFollowUp3Url === 'string' ? data.googleFollowUp3Url : null
    const maybeGoogle7 = typeof data.googleFollowUp7Url === 'string' ? data.googleFollowUp7Url : null
    setGoogleFollowUp3Url(maybeGoogle3)
    setGoogleFollowUp7Url(maybeGoogle7)

    if (sendMode === 'live') {
      setSuccess(`Queued live send to ${selected.fullName} from ${fromAddressLabel}. Delivery updates will appear as webhooks arrive.`)
      setConfirmLive(false)
    } else if (sendMode === 'test_to_self') {
      setSuccess('Queued test email to your own inbox. Review rendering and tone before live send.')
    } else {
      setSuccess('Dry run complete. No email was sent.')
    }
  }

  async function suppressSelected() {
    if (!selected || suppressing) return

    setSuppressing(true)
    setError(null)
    setSuccess(null)

    const res = await fetch('/api/outreach/suppression', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: selected.email,
        reason: 'manual suppression from outreach hub',
        source: 'manual',
      }),
    })
    const { payload, fallbackError } = await readApiPayload(res)

    setSuppressing(false)

    if (!res.ok) {
      setError({
        title: 'Suppression update failed',
        detail: (payload.error as string) ?? fallbackError,
      })
      return
    }

    setItems(prev => prev.map((r) => (r.email === selected.email ? { ...r, status: 'closed' } : r)))
    setSuccess(`Suppressed ${selected.fullName}. Future sends are blocked until unsuppressed.`)
  }

  async function sendCrossChannelFollowUps() {
    if (sendingFollowUps) return
    if (followUpTargets.length === 0) {
      setError({
        title: 'No follow-up targets',
        detail: 'No contacts are currently marked Reached Out across channels.',
      })
      return
    }

    if (sendMode === 'live') {
      const confirmed = window.confirm(`Send follow-up emails to ${followUpTargets.length} reached-out contacts across all channels?`)
      if (!confirmed) return
    }

    setSendingFollowUps(true)
    setError(null)
    setSuccess(null)
    setGuardrailWarnings([])
    setGuardrailViolations([])

    let queuedCount = 0
    let preflightBlockedCount = 0
    let duplicateCount = 0
    const failures: string[] = []
    const sendQueue: ProspectRow[] = []
    const sharedBatchId = globalThis.crypto?.randomUUID?.() ?? `followup_${Date.now()}`
    let resolvedBatchId: string | null = null

    for (const target of followUpTargets) {
      const preflightRes = await fetch('/api/outreach/send', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          fullName: target.fullName,
          company: target.company,
          roleBucket: target.roleBucket,
          emailTo: target.email,
          statusAfter: 'followup_1_sent',
          mode: 'dry_run',
          outreachChannel: target.outreachChannel,
          fitTier: target.fitTier,
          personaFocus: target.personaFocus,
          useLatestTemplateDraft: true,
          templateStep: 'followup_1',
          campaignStep: FOLLOW_UP_CAMPAIGN_STEP,
          idempotencyKey: followUpIdempotencyKey(target),
        }),
      })

      const { payload: preflightPayload, fallbackError: preflightFallback } = await readApiPayload(preflightRes)
      if (!preflightRes.ok) {
        const reason = typeof preflightPayload.error === 'string' && preflightPayload.error.trim().length > 0
          ? preflightPayload.error
          : preflightFallback
        preflightBlockedCount += 1
        failures.push(`${target.fullName}: ${reason}`)
        continue
      }

      sendQueue.push(target)
    }

    if (sendMode === 'dry_run') {
      setSendingFollowUps(false)
      if (preflightBlockedCount > 0) {
        setError({
          title: 'Dry run found blocked follow-ups',
          detail: `${sendQueue.length} ready, ${preflightBlockedCount} blocked in preflight across all channels.`,
          rawReason: failures.slice(0, 4).join(' | '),
        })
      } else {
        setSuccess(`Dry run passed for ${sendQueue.length} follow-up emails across all channels.`)
      }
      return
    }

    for (let i = 0; i < sendQueue.length; i += FOLLOW_UP_BATCH_SIZE) {
      const batch = sendQueue.slice(i, i + FOLLOW_UP_BATCH_SIZE)

      const batchResults = await Promise.all(batch.map(async (target) => {
        const result = await sendFollowUpWithRetry(target, sendMode, sharedBatchId)
        if (!result.ok) {
          return {
            ok: false,
            duplicate: false,
            reason: `${target.fullName}: ${normalizeFollowUpFailureReason(result.reason)}`,
            batchId: null as string | null,
          }
        }

        return { ok: true, duplicate: result.duplicate, reason: '', batchId: result.batchId }
      }))

      for (const result of batchResults) {
        if (!result.ok) {
          failures.push(result.reason)
          continue
        }
        if (result.duplicate) {
          duplicateCount += 1
          continue
        }
        queuedCount += 1
        if (result.batchId) {
          resolvedBatchId = result.batchId
        }
      }

      if (i + FOLLOW_UP_BATCH_SIZE < sendQueue.length) {
        await sleep(FOLLOW_UP_BATCH_DELAY_MS)
      }
    }

    if (queuedCount === 0) {
      setSendingFollowUps(false)
      if (failures.length > 0) {
        setError({
          title: 'No follow-ups were queued',
          detail: `${duplicateCount} duplicates skipped and ${preflightBlockedCount} preflight blocks across ${followUpTargets.length} targets in ${sendMode} mode.`,
          rawReason: failures.slice(0, 4).join(' | '),
        })
        return
      }

      setSuccess(`No new follow-ups queued. ${duplicateCount} duplicate sends were skipped.`)
      return
    }

    if (!resolvedBatchId) {
      setSendingFollowUps(false)
      setError({
        title: 'Batch tracking failed',
        detail: 'Follow-up jobs were queued, but no batch id was returned for status tracking.',
      })
      return
    }

    setSuccess(`Queued ${queuedCount} follow-up emails. Waiting for delivery processing...`)
    const batchStatus = await pollOutreachBatchStatus(resolvedBatchId)
    setSendingFollowUps(false)

    if (!batchStatus.ok) {
      setError({
        title: 'Batch status unavailable',
        detail: `Queued ${queuedCount} follow-ups, but could not confirm completion.`,
        rawReason: batchStatus.reason,
      })
      return
    }

    const summary = batchStatus.summary
    if (summary.failedJobs > 0 || failures.length > 0) {
      const workerFailures = (summary.failedRecipients ?? []).map(item => `${item.recipientEmail}: ${item.message}`)
      setError({
        title: 'Some follow-ups failed',
        detail: `Queued ${queuedCount}; processed ${summary.completedJobs}/${summary.totalJobs}. Failed ${summary.failedJobs}, duplicates ${duplicateCount}, preflight blocks ${preflightBlockedCount}.`,
        rawReason: [...failures, ...workerFailures].slice(0, 4).join(' | '),
      })
      return
    }

    const sentEmails = new Set(sendQueue.map((row) => row.email))
    setItems(prev => prev.map((row) => (sentEmails.has(row.email) ? { ...row, followUpSent: true } : row)))

    const deliveredLike = summary.deliveredJobs + summary.acceptedJobs + summary.repliedJobs
    setSuccess(`Completed follow-up batch: ${deliveredLike} accepted/delivered/replied, ${summary.bouncedJobs} bounced, ${summary.complainedJobs} complained. ${duplicateCount > 0 ? `${duplicateCount} duplicates were skipped.` : ''}`.trim())
  }


  const staleComposerHits = useMemo(() => detectLegacyTemplateCopy(subject, messageText), [subject, messageText])
