import { readFile, readdir } from 'node:fs/promises'
import path from 'node:path'
import { buildOutreachTemplateDraft } from '@/lib/outreach/template-draft'

export type CsvRow = Record<string, string>
export type OutreachChannel = 'executives' | 'search_firms' | 'coaches' | 'outplacement_firms'
export type EmailConfidence = 'high' | 'medium' | 'low'

type CsvSummary = {
  rowCount: number
  rows: CsvRow[]
}

export type ClientRow = {
  fullName: string
  roleBucket: string
  company: string
  email: string
  emailConfidence: EmailConfidence
  status: string
  followUpSent: boolean
  hasLiveOutreach: boolean
  emailOpening: string
  emailBodyCore: string
  defaultSubject: string
  defaultBody: string
  outreachChannel: OutreachChannel
  fitTier: 'strong' | 'medium'
  personaFocus: string
  campaignTag?: 'coach_day1_60'
}

async function findSuffixCompatibleFile(baseDir: string, requestedName: string): Promise<string | null> {
  const firstUnderscore = requestedName.indexOf('_')
  if (firstUnderscore < 0) return null

  const suffix = requestedName.slice(firstUnderscore + 1)
  try {
    const entries = await readdir(baseDir, { withFileTypes: true })
    const match = entries.find((entry) => entry.isFile() && entry.name.endsWith(suffix))
    return match?.name ?? null
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null
    throw error
  }
}

async function readCsvFromDirectory(baseDir: string, fileName: string): Promise<CsvSummary | null> {
  const directPath = path.join(baseDir, fileName)
  try {
    return parseCsv(await readFile(directPath, 'utf8'))
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error
  }

  const fallbackName = await findSuffixCompatibleFile(baseDir, fileName)
  if (!fallbackName) return null

  return parseCsv(await readFile(path.join(baseDir, fallbackName), 'utf8'))
}

function normalizeKeyToken(value: string | undefined): string {
  return (value ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function normalizeCompanyDedupeKey(value: string | undefined): string {
  return normalizeKeyToken(value)
    .replace(/\b(inc|incorporated|corp|corporation|co|company|group|holdings|plc|llc|ltd|limited|partners|partner|firm)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function statusPriority(status: string): number {
  if (status === 'meeting_scheduled') return 5
  if (status === 'in_conversation') return 4
  if (status === 'reached_out') return 3
  if (status === 'prospect') return 2
  if (status === 'closed') return 1
  return 0
}

function rowPriority(row: ClientRow): number {
  let score = 0
  score += row.fitTier === 'strong' ? 200 : 100
  score += emailConfidenceRank(row.emailConfidence) * 10
  score += statusPriority(normalizeStatus(row.status))
  if (row.campaignTag === 'coach_day1_60') score += 1
  return score
}

function preferRow(existing: ClientRow, candidate: ClientRow): ClientRow {
  const existingPriority = rowPriority(existing)
  const candidatePriority = rowPriority(candidate)
  if (candidatePriority > existingPriority) return candidate
  if (candidatePriority < existingPriority) return existing
  return existing
}

/**
 * Dedupe across two scopes:
 * 1) email-level dedupe (exact canonical email)
 * 2) person/company dedupe within the same outreach channel
 */
export function dedupeOutreachRows(rows: ClientRow[]): ClientRow[] {
  const byEmail = new Map<string, ClientRow>()

  for (const row of rows) {
    const emailKey = (row.email ?? '').trim().toLowerCase()
    if (!emailKey) continue

    const existing = byEmail.get(emailKey)
    if (!existing) {
      byEmail.set(emailKey, row)
      continue
    }

    byEmail.set(emailKey, preferRow(existing, row))
  }

  const byPersonCompany = new Map<string, ClientRow>()
  for (const row of byEmail.values()) {
    const normalizedName = normalizeKeyToken(row.fullName)
    const normalizedCompany = normalizeCompanyDedupeKey(row.company)
    const personCompanyKey = normalizedName && normalizedCompany
      ? `${row.outreachChannel}::${normalizedName}::${normalizedCompany}`
      : `${row.outreachChannel}::${row.email}`

    const existing = byPersonCompany.get(personCompanyKey)
    if (!existing) {
      byPersonCompany.set(personCompanyKey, row)
      continue
    }

    byPersonCompany.set(personCompanyKey, preferRow(existing, row))
  }

  return Array.from(byPersonCompany.values())
}

export type ContactStatusRow = {
  email: string | null
  outreach_status: string | null
}

type ExecutiveRoleArchetype =
  | 'cfo'
  | 'coo'
  | 'cio'
  | 'cto'
  | 'chro'
  | 'cro'
  | 'ciso'
  | 'cdo'
  | 'c_suite_other'

export async function readOutreachCsv(fileName: string): Promise<CsvSummary> {
  const sourceDir = path.join(process.cwd(), 'docs', 'outreach')
  const packagedDir = path.join(process.cwd(), '.next', 'server', 'outreach-data')

  const sourceResult = await readCsvFromDirectory(sourceDir, fileName)
  if (sourceResult) return sourceResult

  const packagedResult = await readCsvFromDirectory(packagedDir, fileName)
  if (packagedResult) return packagedResult

  console.warn(`[outreach] CSV unavailable: ${fileName}`)
  return { rowCount: 0, rows: [] }
}

export function prioritizeCuratedRows(base: CsvSummary, curated: CsvSummary, limit = 100): CsvSummary {
  const seenEmails = new Set<string>()
  const prioritized: CsvRow[] = []

  for (const row of [...curated.rows, ...base.rows]) {
    const email = (row.email_guess ?? row.email ?? '').trim().toLowerCase()
    if (!email || seenEmails.has(email)) continue
    seenEmails.add(email)
    prioritized.push(row)
    if (prioritized.length >= limit) break
  }

  return {
    rowCount: prioritized.length,
    rows: prioritized,
  }
}

function parseCsv(content: string): CsvSummary {
  if (!content.trim()) {
    return { rowCount: 0, rows: [] }
  }

  const records: string[][] = []
  let row: string[] = []
  let current = ''
  let inQuotes = false

  for (let i = 0; i < content.length; i++) {
    const ch = content[i]

    if (ch === '"') {
      if (inQuotes && content[i + 1] === '"') {
        current += '"'
        i++
      } else {
        inQuotes = !inQuotes
      }
      continue
    }

    if (ch === ',' && !inQuotes) {
      row.push(current)
      current = ''
      continue
    }

    if ((ch === '\n' || ch === '\r') && !inQuotes) {
      if (ch === '\r' && content[i + 1] === '\n') i++
      row.push(current)
      current = ''
      if (row.some(cell => cell.length > 0)) {
        records.push(row)
      }
      row = []
      continue
    }

    current += ch
  }

  if (current.length > 0 || row.length > 0) {
    row.push(current)
    if (row.some(cell => cell.length > 0)) {
      records.push(row)
    }
  }

  if (records.length === 0) {
    return { rowCount: 0, rows: [] }
  }

  const [headers, ...lines] = records
  const rows = lines.map((cols) => {
    const mapped: CsvRow = {}
    for (let i = 0; i < headers.length; i++) {
      mapped[headers[i]] = cols[i] ?? ''
    }
    return mapped
  })

  return { rowCount: rows.length, rows }
}

export function normalizeStatus(raw: string | undefined): string {
  const status = (raw ?? '').trim().toLowerCase()
  if (status === 'new') return 'prospect'
  if (status === 'first_sent' || status === 'followup_1_sent' || status === 'followup_2_sent') return 'reached_out'
  if (status === 'replied') return 'in_conversation'
  if (status === 'meeting_booked') return 'meeting_scheduled'
  if (status === 'not_a_fit') return 'closed'
  if (['prospect', 'reached_out', 'in_conversation', 'meeting_scheduled', 'closed'].includes(status)) return status
  return 'prospect'
}

function buildDefaultBody(row: CsvRow): string {
  const opening = row.email_opening?.trim() || `I noticed your role at ${row.company} and wanted to send a short, specific note.`
  const core = row.email_body_core?.trim() || 'I work on executive positioning and outreach for senior operators navigating high-stakes transitions.'

  return [
    opening,
    '',
    core,
    '',
    'If useful, I can send a concise follow-up with one specific angle tailored to your priorities.',
    '',
    'Best,',
    'Rich Rothschild',
    'startingmonday.app',
  ].join('\n')
}

function firstNameOf(fullName: string | undefined): string {
  const value = (fullName ?? '').trim()
  if (!value) return 'there'
  const first = value.split(/\s+/)[0]?.trim()
  return first || 'there'
}

function detectExecutiveRoleArchetype(row: CsvRow): ExecutiveRoleArchetype | null {
  const role = canonicalizeLabel(row.role_bucket)
  const title = canonicalizeLabel(row.title)
  const combined = `${role} ${title}`.trim()

  if (!combined) return null

  if (combined.includes('cfo') || combined.includes('chief financial officer')) return 'cfo'
  if (combined.includes('coo') || combined.includes('chief operating officer')) return 'coo'
  if (combined.includes('cio') || combined.includes('chief information officer')) return 'cio'
  if (combined.includes('cto') || combined.includes('chief technology officer')) return 'cto'
  if (combined.includes('chro') || combined.includes('chief human resources officer') || combined.includes('chief people officer')) return 'chro'
  if (combined.includes('cro') || combined.includes('chief revenue officer')) return 'cro'
  if (combined.includes('ciso') || combined.includes('chief information security officer')) return 'ciso'
  if (combined.includes('cdo') || combined.includes('chief data officer') || combined.includes('chief analytics officer')) return 'cdo'

  const cSuiteSignals = ['chief', 'ceo', 'president']
  if (cSuiteSignals.some(signal => combined.includes(signal))) return 'c_suite_other'
  return null
}

function executiveRoleLabel(archetype: ExecutiveRoleArchetype): string {
  if (archetype === 'cfo') return 'CFO'
  if (archetype === 'coo') return 'COO'
  if (archetype === 'cio') return 'CIO'
  if (archetype === 'cto') return 'CTO'
  if (archetype === 'chro') return 'CHRO'
  if (archetype === 'cro') return 'CRO'
  if (archetype === 'ciso') return 'CISO'
  if (archetype === 'cdo') return 'CDO'
  return 'C-suite'
}

function companyToken(company: string | undefined): string {
  const value = (company ?? '').trim()
  return value || 'your organization'
}

function firstNonEmpty(row: CsvRow, keys: string[]): string {
  for (const key of keys) {
    const value = (row[key] ?? '').trim()
    if (value) return value
  }
  return ''
}

export function mapTriggerInputs(row: CsvRow): {
  newsTrigger?: string
  postTrigger?: string
  profileTrigger?: string
} {
  const newsTrigger = firstNonEmpty(row, [
    'trigger_news',
    'news_trigger',
    'recent_news',
    'news_event',
    'company_news',
    'news_summary',
  ])

  const postTrigger = firstNonEmpty(row, [
    'trigger_post',
    'post_trigger',
    'recent_post',
    'linkedin_post',
    'social_post',
    'post_summary',
  ])

  const profileTrigger = firstNonEmpty(row, [
    'trigger_profile',
    'profile_trigger',
    'profile_signal',
    'personalization_line',
    'profile_note',
    'contact_note',
    'notes',
  ])

  return {
    ...(newsTrigger ? { newsTrigger } : {}),
    ...(postTrigger ? { postTrigger } : {}),
    ...(profileTrigger ? { profileTrigger } : {}),
  }
}

function sourceTemplateDraft(row: CsvRow): { subject: string; body: string } | null {
  const subject = (row.default_subject ?? row.subject ?? row.email_subject ?? '').trim()
  const body = (row.default_body ?? row.email_body ?? row.email_text ?? row.email_body_core ?? '').trim()

  if (!subject && !body) return null

  return {
    subject: subject || buildDefaultSubject(row),
    body: body || buildDefaultBody(row),
  }
}

export function buildStandardizedDraft(
  row: CsvRow,
  channel: OutreachChannel,
  options?: { forceTemplate?: boolean },
): { subject: string; body: string } {
  void options

  const firstName = firstNameOf(row.full_name)
  const company = companyToken(row.company)
  const archetype = detectExecutiveRoleArchetype(row)
  const roleLabel = archetype ? executiveRoleLabel(archetype) : (row.role_bucket || 'Executive')
  const triggers = mapTriggerInputs(row)

  const draft = buildOutreachTemplateDraft({
    channel,
    fullName: row.full_name,
    firstName,
    company,
    roleLabel,
    focus: row.persona_focus || row.role_bucket || row.title || roleLabel,
    step: row.step,
    state: row.state,
    newsTrigger: triggers.newsTrigger,
    postTrigger: triggers.postTrigger,
    profileTrigger: triggers.profileTrigger,
  })

  return {
    subject: draft.subject,
    body: draft.body,
  }
}

function buildDefaultSubject(row: CsvRow): string {
  const role = row.role_bucket?.toUpperCase() || 'Executive'
  return `A specific ${role} angle for ${row.company}`
}

export function normalizeFitTier(raw: string | undefined): 'strong' | 'medium' {
  const fit = (raw ?? '').trim().toLowerCase()
  return fit === 'medium' ? 'medium' : 'strong'
}

function canonicalizeLabel(value: string | undefined): string {
  return (value ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

function normalizeCompanyKey(value: string | undefined): string {
  return canonicalizeLabel(value)
    .replace(/\b(inc|incorporated|corp|corporation|co|company|group|holdings|plc|llc|ltd|limited|communications)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function parseCompanySizeBand(value: string | undefined): 'target' | 'other' | 'unknown' {
  const normalized = canonicalizeLabel(value)
  if (!normalized) return 'unknown'

  if (normalized.includes('1001 10000')) return 'target'
  if (normalized.includes('10001')) return 'other'
  if (normalized.includes('enterprise') || normalized.includes('startup') || normalized.includes('small')) return 'other'

  const numeric = Number(normalized.replace(/[^0-9]/g, ''))
  if (Number.isFinite(numeric) && numeric > 0) {
    if (numeric > 1000 && numeric < 10000) return 'target'
    return 'other'
  }

  return 'unknown'
}

function roleTokens(value: string): Set<string> {
  const normalized = canonicalizeLabel(value)
  const roles = new Set<string>()

  if (!normalized) return roles

  const add = (...items: string[]) => items.forEach(item => roles.add(item))

  if (normalized.includes('cfo') || normalized.includes('chief financial officer')) add('cfo', 'chief financial officer')
  if (normalized.includes('coo') || normalized.includes('chief operating officer')) add('coo', 'chief operating officer')
  if (normalized.includes('cio') || normalized.includes('chief information officer')) add('cio', 'chief information officer')
  if (normalized.includes('chro') || normalized.includes('chief human resources officer') || normalized.includes('chief people officer')) add('chro', 'chief people officer')
  if (normalized.includes('cro') || normalized.includes('chief revenue officer')) add('cro', 'chief revenue officer')
  if (normalized.includes('cto') || normalized.includes('chief technology officer')) add('cto', 'chief technology officer')
  if (normalized.includes('ciso') || normalized.includes('chief information security officer')) add('ciso', 'chief information security officer')
  if (normalized.includes('cdo') || normalized.includes('chief data officer')) add('cdo', 'chief data officer')
  if (normalized.includes('chief analytics officer')) add('chief analytics officer')
  if (normalized.includes('vp it') || normalized.includes('vp information technology')) add('vp it', 'vp information technology')
  if (normalized.includes('vp sales')) add('vp sales')
  if (normalized.includes('vp revenue')) add('vp revenue')
  if (normalized.includes('vp technology')) add('vp technology')
  if (normalized.includes('vp engineering')) add('vp engineering')

  if (roles.size === 0) {
    roles.add(normalized)
  }

  return roles
}

export function buildExecutiveFitLookup(rows: CsvRow[]): Map<string, Map<string, 'strong' | 'medium'>> {
  const lookup = new Map<string, Map<string, 'strong' | 'medium'>>()

  for (const row of rows) {
    const companyKey = normalizeCompanyKey(row.target_account ?? row.company)
    const title = row.target_title ?? row.title ?? row.role_bucket
    const fitTier = normalizeFitTier(row.fit_tier)
    const roleSet = roleTokens(title ?? '')

    if (!companyKey || roleSet.size === 0) continue

    const companyRoles = lookup.get(companyKey) ?? new Map<string, 'strong' | 'medium'>()
    for (const role of roleSet) {
      const existing = companyRoles.get(role)
      if (existing === 'strong') continue
      companyRoles.set(role, fitTier)
    }
    lookup.set(companyKey, companyRoles)
  }

  return lookup
}

export function buildExecutiveCompanySizeLookup(rows: CsvRow[]): Map<string, 'target' | 'other'> {
  const lookup = new Map<string, 'target' | 'other'>()

  for (const row of rows) {
    const companyKey = normalizeCompanyKey(row.target_account ?? row.company)
    const sizeBand = parseCompanySizeBand(row.company_size_band ?? row.company_size)
    if (!companyKey || sizeBand === 'unknown') continue

    const existing = lookup.get(companyKey)
    if (existing === 'target') continue
    lookup.set(companyKey, sizeBand)
  }

  return lookup
}

export function executivePersonaFit(
  row: CsvRow,
  fitLookup: Map<string, Map<string, 'strong' | 'medium'>>,
  companySizeLookup: Map<string, 'target' | 'other'>,
): 'strong' | 'medium' | null {
  const companyKey = normalizeCompanyKey(row.company)
  const companySizeFromRow = parseCompanySizeBand(row.company_size_band ?? row.company_size)
  const companySize = companySizeFromRow === 'unknown' ? (companySizeLookup.get(companyKey) ?? 'unknown') : companySizeFromRow

  if (companySize !== 'target') return null

  const explicitFit = (row.fit_tier ?? '').trim().toLowerCase()
  if (explicitFit === 'strong' || explicitFit === 'medium') return explicitFit

  const roleCandidates = roleTokens(`${row.role_bucket ?? ''} ${row.title ?? ''}`)

  if (companyKey && roleCandidates.size > 0) {
    const companyRoles = fitLookup.get(companyKey)
    if (companyRoles) {
      for (const role of roleCandidates) {
        const matched = companyRoles.get(role)
        if (matched) return matched
      }
    }
  }

  const role = canonicalizeLabel(row.role_bucket)
  const title = canonicalizeLabel(row.title)
  const combined = `${role} ${title}`.trim()

  const strongSignals = [
    'cfo',
    'coo',
    'cio',
    'chro',
    'chief people officer',
    'cro',
    'chief revenue officer',
    'vp it',
    'vp information technology',
    'vp sales',
    'vp revenue',
  ]

  const mediumSignals = [
    'cto',
    'vp technology',
    'vp engineering',
    'ciso',
    'chief information security officer',
    'cdo',
    'chief data officer',
    'chief analytics officer',
  ]

  let score = 0

  if (strongSignals.some(signal => combined.includes(signal))) score += 70
  if (mediumSignals.some(signal => combined.includes(signal))) score += 45

  const sourceType = canonicalizeLabel(row.source_type)
  if (sourceType.includes('leadership') || sourceType.includes('investor') || sourceType.includes('company')) {
    score += 10
  }

  const confidence = (row.confidence ?? row.email_confidence ?? '').trim().toLowerCase()
  if (confidence === 'high') score += 10
  if (confidence === 'medium') score += 5

  if (score >= 70) return 'strong'
  if (score >= 45) return 'medium'
  return null
}

function normalizeEmailConfidence(raw: string | undefined): EmailConfidence | null {
  const confidence = (raw ?? '').trim().toLowerCase()
  if (confidence === 'high' || confidence === 'medium' || confidence === 'low') return confidence
  return null
}

export function inferEmailConfidence(row: CsvRow): EmailConfidence {
  const explicit = normalizeEmailConfidence(row.email_confidence)
  if (explicit) return explicit

  const email = (row.email_guess ?? row.email ?? '').trim().toLowerCase()
  const company = (row.company ?? '').trim().toLowerCase()
  const sourceType = (row.source_type ?? '').trim().toLowerCase()

  const domain = email.includes('@') ? email.split('@')[1] : ''
  const domainRoot = domain.split('.')[0] ?? ''
  const freeEmailDomains = new Set(['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'aol.com'])
  if (!domain || freeEmailDomains.has(domain)) return 'low'

  const stopWords = new Set(['inc', 'llc', 'ltd', 'group', 'partners', 'partner', 'search', 'executive', 'leadership', 'advisors'])
  const companyTokens = company
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .map(token => token.trim())
    .filter(token => token.length >= 4 && !stopWords.has(token))

  const domainMatchesCompany = companyTokens.some(token => domainRoot.includes(token) || token.includes(domainRoot))

  if (sourceType.includes('verified')) return 'high'
  if (sourceType.includes('curated') && domainMatchesCompany) return 'high'
  if (sourceType.includes('inferred') && domainMatchesCompany) return 'medium'
  if (domainMatchesCompany) return 'high'
  if (sourceType.includes('inferred')) return 'low'
  return 'medium'
}

export function emailConfidenceRank(confidence: EmailConfidence): number {
  if (confidence === 'high') return 3
  if (confidence === 'medium') return 2
  return 1
}

export function mergeFirstTouch(master: CsvSummary, firstTouch: CsvSummary): CsvSummary {
  const byName = new Map<string, CsvRow>()
  for (const row of firstTouch.rows) {
    byName.set((row.full_name ?? '').trim().toLowerCase(), row)
  }

  const merged = master.rows.map((row) => {
    const touch = byName.get((row.full_name ?? '').trim().toLowerCase())
    return {
      ...row,
      // Keep matching metadata from first-touch rows, but do not carry forward
      // legacy subject/body copy as defaults.
      ...(touch ? touch : {}),
      default_subject: buildDefaultSubject(row),
      default_body: buildDefaultBody(row),
    }
  })

  return { rowCount: merged.length, rows: merged }
}

function rowCompletenessScore(row: CsvRow): number {
  const fields = [
    row.email_guess,
    row.email,
    row.role_bucket,
    row.title,
    row.default_subject,
    row.default_body,
    row.subject,
    row.email_text,
    row.email_opening,
    row.email_body_core,
    row.personalization_line,
    row.persona_focus,
  ]
  return fields.reduce((sum, value) => sum + ((value ?? '').trim().length > 0 ? 1 : 0), 0)
}

function normalizeExecutiveRow(row: CsvRow): CsvRow {
  return {
    ...row,
    default_subject: (row.default_subject ?? '').trim() || (row.subject ?? '').trim(),
    default_body: (row.default_body ?? '').trim() || (row.email_text ?? '').trim(),
    email_opening: (row.email_opening ?? '').trim() || (row.personalization_line ?? '').trim(),
    email_body_core: (row.email_body_core ?? '').trim() || (row.email_text ?? '').trim(),
  }
}

export function combineExecutiveSources(sources: CsvSummary[]): CsvSummary {
  const byKey = new Map<string, CsvRow>()

  for (const source of sources) {
    for (const rawRow of source.rows) {
      const row = normalizeExecutiveRow(rawRow)
      const email = (row.email_guess ?? row.email ?? '').trim().toLowerCase()
      const fallbackKey = `${(row.full_name ?? '').trim().toLowerCase()}|${(row.company ?? '').trim().toLowerCase()}`
      const key = email || fallbackKey
      if (!key) continue

      const existing = byKey.get(key)
      if (!existing) {
        byKey.set(key, row)
        continue
      }

      if (rowCompletenessScore(row) > rowCompletenessScore(existing)) {
        byKey.set(key, row)
      }
    }
  }

  const rows = Array.from(byKey.values())
  return { rowCount: rows.length, rows }
}

export function statusByEmail(rows: ContactStatusRow[]): Map<string, string> {
  const byEmail = new Map<string, string>()
  for (const row of rows) {
    const email = (row.email ?? '').trim().toLowerCase()
    if (!email) continue
    byEmail.set(email, normalizeStatus(row.outreach_status ?? 'prospect'))
  }
  return byEmail
}

export function followUpSentByEmail(rows: ContactStatusRow[]): Set<string> {
  const sent = new Set<string>()
  for (const row of rows) {
    const email = (row.email ?? '').trim().toLowerCase()
    const status = (row.outreach_status ?? '').trim().toLowerCase()
    if (!email) continue
    if (status === 'followup_1_sent' || status === 'followup_2_sent') {
      sent.add(email)
    }
  }
  return sent
}

#!/usr/bin/env node
/**
 * Luxury Page Sentinel
 *
 * Inventory-driven audit of EVERY route in src/app:
 *  1. Source palette audit (all pages, including auth-gated ones):
 *     flags light-shell palettes that violate the dark luxury standard.
 *  2. Runtime availability audit (all static routes against a live base URL):
 *     flags non-200 responses, 404 marker text, and slow responses.
 *  3. Rendered verification (screenshot-based darkness/contrast metrics):
 *     flags visual regressions in darkness discipline and text contrast.
 *  4. Layout-shift diff detection: flags CSS bleed and unexpected visual changes.
 *
 * Reports failures to Slack when SLACK_WEBHOOK_URL is set.
 * Exits 1 when any blocking violation is found (unless --report-only).
 *
 * Usage:
 *   node scripts/luxury-page-sentinel.mjs [--base-url=https://startingmonday.app] [--report-only] [--output-json=tmp/luxury-sentinel.json] [--skip-rendered]
 */
import fs from 'node:fs'
import path from 'node:path'
import { chromium } from '@playwright/test'
import { postSlackText, writeLatestReportFiles } from './lib/agent-report-kit.mjs'

const ROOT = process.cwd()
const argv = process.argv.slice(2)
const reportOnly = argv.includes('--report-only')
const failOnBlocking = argv.includes('--fail-on-blocking')
const skipRuntime = argv.includes('--skip-runtime')
const skipRendered = argv.includes('--skip-rendered')
const baseUrlArg = argv.find((a) => a.startsWith('--base-url='))
const outputJsonArg = argv.find((a) => a.startsWith('--output-json='))
const BASE_URL = (baseUrlArg?.split('=')[1] || process.env.SENTINEL_BASE_URL || 'https://startingmonday.app').replace(/\/$/, '')
const OUTPUT_JSON = outputJsonArg?.split('=')[1] || 'tmp/luxury-page-sentinel.json'
const STATUS_JSON = path.join(ROOT, 'docs', 'status', 'luxury-page-sentinel.latest.json')
const STATUS_MD = path.join(ROOT, 'docs', 'status', 'luxury-page-sentinel.latest.md')
const QUARANTINE_JSON = path.join(ROOT, 'config', 'luxury-page-sentinel-quarantine.json')
const DEBT_BASELINE_JSON = path.join(ROOT, 'config', 'luxury-page-sentinel-debt-baseline.json')
const SCREENSHOTS_DIR = path.join(ROOT, 'tmp', 'sentinel-screenshots')
const SCREENSHOT_DIFFS_DIR = path.join(ROOT, 'tmp', 'sentinel-diffs')

const rubric = JSON.parse(fs.readFileSync(path.join(ROOT, 'config', 'luxury-page-sentinel-rubric.json'), 'utf8'))
const quarantine = fs.existsSync(QUARANTINE_JSON)
  ? JSON.parse(fs.readFileSync(QUARANTINE_JSON, 'utf8'))
  : { version: 1, entries: [] }
const debtBaseline = fs.existsSync(DEBT_BASELINE_JSON)
  ? JSON.parse(fs.readFileSync(DEBT_BASELINE_JSON, 'utf8'))
  : { version: 1, maxByDimension: {} }

// ── Route inventory ──────────────────────────────────────────────────────────
function collectPageFiles(dir, acc = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) collectPageFiles(full, acc)
    else if (entry.name === 'page.tsx' || entry.name === 'page.ts') acc.push(full)
  }
  return acc
}

function routeFromFile(relativePath) {
  // src/app/(group)/a/b/page.tsx -> /a/b
  const parts = relativePath
    .replace(/\\/g, '/')
    .replace(/^src\/app\//, '')
    .replace(/(^|\/)page\.tsx?$/, '')
    .split('/')
    .filter((seg) => seg && !(seg.startsWith('(') && seg.endsWith(')')))
  return '/' + parts.join('/')
}

const appDir = path.join(ROOT, 'src', 'app')
const pageFiles = collectPageFiles(appDir).map((f) => path.relative(ROOT, f).replace(/\\/g, '/'))
const inventory = pageFiles.map((relativePath) => {
  const route = routeFromFile(relativePath) || '/'
  return {
    relativePath,
    route: route === '' ? '/' : route,
    dynamic: /\[[^\]]+\]/.test(route),
    authGated: relativePath.startsWith('src/app/(dashboard)/') || relativePath.startsWith('src/app/settings/') || relativePath.startsWith('src/app/coach/'),
  }
})

// ── 1. Source palette audit ──────────────────────────────────────────────────
const LIGHT_SHELL_RE = /className\s*=\s*["'`][^"'`]*min-h-screen[^"'`]*(bg-slate-50|bg-slate-100|bg-gray-50|bg-gray-100)[^"'`]*["'`]|className\s*=\s*["'`][^"'`]*(bg-slate-50|bg-slate-100|bg-gray-50|bg-gray-100)[^"'`]*min-h-screen[^"'`]*["'`]/
// Light opaque card containers on the dark shell (e.g. bg-white/95 onboarding card).
const LIGHT_CARD_RE = /className\s*=\s*["'`][^"'`]*bg-white\/9[05][^"'`]*["'`]/

// Scan every non-test .tsx under src/app so client components cannot hide drift.
function collectTsxFiles(dir, acc = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) collectTsxFiles(full, acc)
    else if (entry.name.endsWith('.tsx') && !entry.name.includes('.test.')) acc.push(full)
  }
  return acc
}

function nearestRoute(relativePath) {
  // Attribute a component file to the closest ancestor directory containing page.tsx
  let dir = path.posix.dirname(relativePath)
  while (dir.startsWith('src/app')) {
    if (fs.existsSync(path.join(ROOT, dir, 'page.tsx'))) {
      return routeFromFile(`${dir}/page.tsx`) || '/'
    }
    dir = path.posix.dirname(dir)
  }
  return '(shared-component)'
}

const tsxFiles = [
  ...collectTsxFiles(appDir),
  ...collectTsxFiles(path.join(ROOT, 'src', 'components')),
].map((f) => path.relative(ROOT, f).replace(/\\/g, '/'))
const paletteViolations = []
const typographyViolations = []
const accentViolations = []
const routeVisualDiscipline = new Map()

function ensureRouteVisualEntry(route) {
  if (!routeVisualDiscipline.has(route)) {
    routeVisualDiscipline.set(route, {
      fontFamilies: new Set(),
      accentFamilies: new Set(),
      relativePaths: new Set(),
    })
  }
  return routeVisualDiscipline.get(route)
}

function countedFontFamilies(families) {
  const countMono = rubric.visualDiscipline?.fontFamilies?.countMonospaceAgainstLimit ?? false
  return [...families].filter((family) => countMono || family !== 'font-mono')
}

const FONT_FAMILY_RE = /font-(sans|serif|mono)\b/g
const ACCENT_FAMILY_RE = /(?:text|bg|border)-(amber|orange|yellow|emerald|green|teal|cyan|blue|indigo|violet|purple|pink|rose|red)-/g

for (const relativePath of tsxFiles) {
  const source = fs.readFileSync(path.join(ROOT, relativePath), 'utf8')
  const route = nearestRoute(relativePath)
  const routeEntry = ensureRouteVisualEntry(route)
  routeEntry.relativePaths.add(relativePath)

  for (const match of source.matchAll(FONT_FAMILY_RE)) {
    routeEntry.fontFamilies.add(`font-${match[1]}`)
  }

  for (const match of source.matchAll(ACCENT_FAMILY_RE)) {
    routeEntry.accentFamilies.add(match[1])
  }

  const shellMatch = source.match(LIGHT_SHELL_RE)
  const cardMatch = source.match(LIGHT_CARD_RE)
  const match = shellMatch ?? cardMatch
  if (match) {
    paletteViolations.push({
      route,
      relativePath,
      dimension: 'palette-conformance',
      evidence: match[0].slice(0, 160),
    })
  }
}

for (const [route, entry] of routeVisualDiscipline.entries()) {
  const scope = routeScope(route)
  const fontThreshold = rubric.visualDiscipline?.fontFamilies?.maxDistinctFamiliesByScope?.[scope] ?? 2
  const accentThreshold = rubric.visualDiscipline?.accentFamilies?.maxDistinctFamiliesByScope?.[scope] ?? 2
  const countedFamilies = countedFontFamilies(entry.fontFamilies)

  if (countedFamilies.length > fontThreshold) {
    typographyViolations.push({
      route,
      dimension: 'typography-discipline',
      blocking: false,
      evidence: `${countedFamilies.length} distinct families (${countedFamilies.join(', ')}) > ${fontThreshold} for ${scope}`,
    })
  }

  if (entry.accentFamilies.size > accentThreshold) {
    accentViolations.push({
      route,
      dimension: 'accent-restraint',
      blocking: false,
      evidence: `${entry.accentFamilies.size} accent families (${[...entry.accentFamilies].sort().join(', ')}) > ${accentThreshold} for ${scope}`,
    })
  }
}

// ── 2. Runtime availability audit ────────────────────────────────────────────
const runtimeViolations = []
const runtimeChecked = []

async function checkRoute(route) {
  const url = `${BASE_URL}${route}`
  const startedAt = Date.now()
  try {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), rubric.runtime.maxResponseMs + 4000)
    const res = await fetch(url, { redirect: 'follow', signal: controller.signal, headers: { 'user-agent': 'luxury-page-sentinel/1.0' } })
    clearTimeout(timer)
    const elapsedMs = Date.now() - startedAt
    const body = await res.text()
    // Markers use rendered-markup form (">text<") so the escaped copy of the
    // not-found template inside the RSC flight payload does not false-positive.
    const notFoundHit = rubric.runtime.notFoundMarkers.find((marker) => body.includes(marker))

    runtimeChecked.push({ route, status: res.status, elapsedMs })

    if (!rubric.runtime.allowedStatusCodes.includes(res.status)) {
      runtimeViolations.push({ route, dimension: 'availability', evidence: `HTTP ${res.status} at ${url}` })
    } else if (notFoundHit) {
      runtimeViolations.push({ route, dimension: 'availability', evidence: `404 marker "${notFoundHit}" rendered at ${url}` })
    } else if (elapsedMs > rubric.runtime.maxResponseMs) {
      runtimeViolations.push({ route, dimension: 'latency', blocking: false, evidence: `${elapsedMs}ms > ${rubric.runtime.maxResponseMs}ms at ${url}` })
    }
  } catch (err) {
    runtimeViolations.push({ route, dimension: 'availability', evidence: `fetch failed at ${url}: ${err.message}` })
  }
}

async function runPool(items, worker, size = 8) {
  const queue = [...items]
  const workers = Array.from({ length: size }, async () => {
    while (queue.length > 0) {
      const item = queue.shift()
      if (item !== undefined) await worker(item)
    }
  })
  await Promise.all(workers)
}

// ── 3. Rendered verification (screenshot-based darkness/contrast) ────────────
const renderedViolations = []
const screenshotMetrics = new Map()

function estimateDarknessMetrics(pixels) {
  // Simplified darkness calculation from pixel data
  // pixels is Uint8ClampedArray of RGBA values
  let darkPixels = 0
  for (let i = 0; i < pixels.length; i += 4) {
    const r = pixels[i]
    const g = pixels[i + 1]
    const b = pixels[i + 2]
    const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255
    if (luminance < 0.2) darkPixels += 1
  }
  const totalPixels = pixels.length / 4
  const darkShareProxy = totalPixels > 0 ? darkPixels / totalPixels : 0
  return { darkPixels, totalPixels, darkShareProxy }
}

function buildMarkdown(summary) {
  const lines = []
  lines.push('# Luxury Page Sentinel Report')
  lines.push('')
  lines.push(`Generated: ${summary.generatedAt}`)
  lines.push(`Base URL: ${summary.baseUrl}`)
  lines.push(`Routes discovered: ${summary.routesDiscovered}`)
  lines.push(`Coverage: ${summary.coverage.coveragePct}%`)
  lines.push(`Blocking violations: ${summary.blockingViolations}`)
  lines.push('')
  lines.push('## Summary')
  lines.push('')
  lines.push(`- Palette violations: ${summary.paletteViolations}`)
  lines.push(`- Typography warnings: ${summary.typographyWarnings}`)
  lines.push(`- Accent warnings: ${summary.accentWarnings}`)
  lines.push(`- Availability violations: ${summary.availabilityViolations}`)
  lines.push(`- Rendered violations: ${summary.renderedViolations}`)
  lines.push(`- Debt ratchet pass: ${summary.debtRatchet.pass}`)
  lines.push('')
  lines.push('## Top Incident Patterns')
  lines.push('')
  if (!summary.incidents?.top?.length) {
    lines.push('- None')
  } else {
    for (const incident of summary.incidents.top.slice(0, 20)) {
      lines.push(`- [${incident.dimension}/${incident.scope}] routes=${incident.routeCount} :: ${incident.signature}`)
    }
  }
  lines.push('')
  return `${lines.join('\n')}\n`
}

async function captureScreenshot(url, route) {
  let browser
  try {
    browser = await chromium.launch()
    const context = await browser.newContext()
    const page = await context.newPage()
    page.setDefaultTimeout(10000)
    page.setDefaultNavigationTimeout(10000)
    
    await page.goto(url, { waitUntil: 'networkidle' })
    await page.waitForLoadState('networkidle')

    const screenshotPath = path.join(SCREENSHOTS_DIR, `${route.replace(/\//g, '_')}.png`)
    fs.mkdirSync(SCREENSHOTS_DIR, { recursive: true })
    await page.screenshot({ path: screenshotPath, fullPage: false })

    // Extract pixel data from viewport for darkness analysis
    const pixelData = await page.evaluate(() => {
      const canvas = document.createElement('canvas')
      const ctx = canvas.getContext('2d')
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
      ctx.fillStyle = '#000000'
      ctx.fillRect(0, 0, canvas.width, canvas.height)
      
      // Simple DOM traversal to estimate background colors
      const elements = document.querySelectorAll('body, [class*="bg-"]')
      let darkCount = 0
      for (const el of elements) {
        const bg = window.getComputedStyle(el).backgroundColor
        if (bg && (bg.includes('rgb(0') || bg.includes('rgb(15') || bg.includes('rgb(25') || bg.includes('rgb(30'))) {
          darkCount += 1
        }
      }
      return { darkElementsEstimate: darkCount, totalElements: elements.length }
    })

    await page.close()
    await context.close()

    return { success: true, screenshotPath, pixelEstimate: pixelData }
  } catch (err) {
    renderedViolations.push({
      route,
      dimension: 'rendered-capture',
      evidence: `Screenshot capture failed: ${err.message}`,
    })
    return { success: false, error: err.message }
  } finally {
    if (browser) await browser.close()
  }
}

async function checkRenderedDarkness(route) {
  const url = `${BASE_URL}${route}`
  const result = await captureScreenshot(url, route)
  
  if (!result.success) return
  
  const minDarkShareProxy = rubric.visualDiscipline?.minDarkShareProxy ?? 0.7
  const estimatedDarkShare = (result.pixelEstimate?.darkElementsEstimate ?? 0) / (result.pixelEstimate?.totalElements ?? 1)
  
  screenshotMetrics.set(route, {
    screenshotPath: result.screenshotPath,
    estimatedDarkShare,
    timestamp: new Date().toISOString(),
  })

  // Advisory check for darkness discipline (not blocking for now)
  if (estimatedDarkShare < minDarkShareProxy) {
    renderedViolations.push({
      route,
      dimension: 'rendered-darkness',
      blocking: false,
      evidence: `Estimated dark share ${(estimatedDarkShare * 100).toFixed(1)}% < ${(minDarkShareProxy * 100).toFixed(1)}% threshold`,
    })
  }
}

const staticRoutes = inventory.filter((p) => !p.dynamic).map((p) => p.route)

if (!skipRuntime) {
  await runPool(staticRoutes, checkRoute, 8)
}

if (!skipRendered && !skipRuntime) {
  // Capture screenshots for top routes (sample to avoid timeout)
  const topRoutes = staticRoutes.filter((r) => !r.includes('[') && (r === '/' || r.startsWith('/pricing') || r.startsWith('/demo') || r.startsWith('/blog')))
  await runPool(topRoutes.slice(0, 5), checkRenderedDarkness, 2)
}

// ── Coverage contract: every route gets an explicit verdict ─────────────────
const allowedSkipReasons = new Set(rubric.coverage?.allowedSkipReasons ?? [])
const paletteFailRoutes = new Set(paletteViolations.map((v) => v.route))
const runtimeFailRoutes = new Set(runtimeViolations.filter((v) => v.blocking !== false).map((v) => v.route))
const runtimeCheckedRoutes = new Set(runtimeChecked.map((r) => r.route))

const verdicts = inventory.map((page) => {
  if (page.dynamic) {
    return paletteFailRoutes.has(page.route)
      ? { route: page.route, verdict: 'fail', reason: 'palette-conformance' }
      : { route: page.route, verdict: 'skip', reason: 'dynamic-route-not-sampled' }
  }
  if (skipRuntime) {
    return paletteFailRoutes.has(page.route)
      ? { route: page.route, verdict: 'fail', reason: 'palette-conformance' }
      : { route: page.route, verdict: 'skip', reason: 'runtime-skipped-by-flag' }
  }
  if (!runtimeCheckedRoutes.has(page.route) && !runtimeFailRoutes.has(page.route)) {
    // Route was in inventory but never received a runtime result and no failure was recorded.
    return { route: page.route, verdict: 'gap', reason: 'no-verdict-recorded' }
  }
  const failed = runtimeFailRoutes.has(page.route) || paletteFailRoutes.has(page.route)
  return { route: page.route, verdict: failed ? 'fail' : 'pass', reason: null }
})

const coverageViolations = verdicts
  .filter((v) => v.verdict === 'gap' || (v.verdict === 'skip' && !allowedSkipReasons.has(v.reason)))
  .map((v) => ({
    route: v.route,
    dimension: 'coverage',
    evidence: v.verdict === 'gap'
      ? 'route received no verdict (unexplained coverage gap)'
      : `skip reason "${v.reason}" is not allowlisted`,
  }))

const skipCounts = {}
for (const v of verdicts) {
  if (v.verdict === 'skip') skipCounts[v.reason] = (skipCounts[v.reason] ?? 0) + 1
}

const verdictTotals = {
  total: verdicts.length,
  passed: verdicts.filter((v) => v.verdict === 'pass').length,
  failed: verdicts.filter((v) => v.verdict === 'fail').length,
  skipped: verdicts.filter((v) => v.verdict === 'skip').length,
  gaps: verdicts.filter((v) => v.verdict === 'gap').length,
}
const coveragePct = verdictTotals.total === 0
  ? 0
  : Number((((verdictTotals.passed + verdictTotals.failed) / verdictTotals.total) * 100).toFixed(1))

function routeScope(route) {
  if (route.startsWith('/dashboard')) return 'dashboard'
  if (route === '/' || route.startsWith('/pricing') || route.startsWith('/demo') || route.startsWith('/blog') || route.startsWith('/method-and-evidence') || route.startsWith('/signup')) {
    return 'funnel'
  }
  return 'public'
}

function evidenceSignature(violation) {
  if (violation.dimension === 'palette-conformance') {
    const classHit = violation.evidence.match(/className=\"[^\"]+\"/)
    return classHit ? classHit[0].slice(0, 120) : violation.evidence.slice(0, 120)
  }

  if (violation.dimension === 'availability') {
    const statusHit = violation.evidence.match(/HTTP\s+(\d{3})/)
    if (statusHit) return `http-${statusHit[1]}`
    if (violation.evidence.includes('404 marker')) return 'rendered-404-marker'
    if (violation.evidence.includes('fetch failed')) return 'fetch-failed'
  }

  if (violation.dimension === 'coverage') {
    return violation.evidence.includes('allowlisted') ? 'skip-reason-not-allowlisted' : 'unexplained-coverage-gap'
  }

  return violation.evidence.slice(0, 120)
}

function buildIncidents(violations) {
  const buckets = new Map()

  for (const violation of violations) {
    const scope = routeScope(violation.route)
    const signature = evidenceSignature(violation)
    const key = `${violation.dimension}|${scope}|${signature}`

    if (!buckets.has(key)) {
      buckets.set(key, {
        key,
        dimension: violation.dimension,
        scope,
        signature,
        evidence: violation.evidence,
        routes: new Set(),
      })
    }

    buckets.get(key).routes.add(violation.route)
  }

  const severityWeight = { availability: 4, coverage: 3, 'palette-conformance': 2 }
  return [...buckets.values()]
    .map((incident) => {
      const routes = [...incident.routes].sort()
      const routeCount = routes.length
      const weight = severityWeight[incident.dimension] ?? 1
      return {
        key: incident.key,
        dimension: incident.dimension,
        scope: incident.scope,
        signature: incident.signature,
        evidence: incident.evidence,
        routeCount,
        routes,
        sampleRoutes: routes.slice(0, 5),
        score: routeCount * weight,
      }
    })
    .sort((a, b) => b.score - a.score || b.routeCount - a.routeCount || a.dimension.localeCompare(b.dimension))
}

function applyQuarantine(violations) {
  const now = Date.now()
  const entries = Array.isArray(quarantine.entries) ? quarantine.entries : []
  const active = entries.filter((entry) => !entry.expiresAt || new Date(entry.expiresAt).getTime() > now)
  const expired = entries.filter((entry) => entry.expiresAt && new Date(entry.expiresAt).getTime() <= now)

  const isMatch = (entry, violation) => {
    if (entry.route !== violation.route) return false
    if (entry.dimension !== violation.dimension) return false
    if (entry.signatureIncludes && !violation.evidence.includes(entry.signatureIncludes)) return false
    return true
  }

  const suppressed = []
  const unsuppressed = []
  for (const violation of violations) {
    const matched = active.find((entry) => isMatch(entry, violation))
    if (matched) {
      suppressed.push({
        route: violation.route,
        dimension: violation.dimension,
        evidence: violation.evidence,
        quarantine: {
          ticket: matched.ticket ?? null,
          owner: matched.owner ?? null,
          expiresAt: matched.expiresAt ?? null,
          reason: matched.reason ?? null,
        },
      })
      continue
    }
    unsuppressed.push(violation)
  }

  const expiredViolations = expired.map((entry) => ({
    route: entry.route ?? '(quarantine-entry)',
    dimension: 'quarantine',
    evidence: `expired quarantine entry (ticket=${entry.ticket ?? 'n/a'}, owner=${entry.owner ?? 'n/a'}, expired=${entry.expiresAt})`,
  }))

  return {
    unsuppressed,
    suppressed,
    expiredViolations,
    stats: {
      activeEntries: active.length,
      expiredEntries: expired.length,
      suppressedFindings: suppressed.length,
    },
  }
}

function applyDebtRatchet(violations) {
  const byDimension = violations.reduce((acc, violation) => {
    acc[violation.dimension] = (acc[violation.dimension] ?? 0) + 1
    return acc
  }, {})

  const checks = []
  const violationsOut = []
  const maxByDimension = debtBaseline.maxByDimension ?? {}

  for (const [dimension, max] of Object.entries(maxByDimension)) {
    const current = byDimension[dimension] ?? 0
    const pass = current <= max
    checks.push({ dimension, max, current, pass })
    if (!pass) {
      violationsOut.push({
        route: '(portfolio)',
        dimension: 'debt-ratchet',
        evidence: `${dimension} debt increased (${current} > ${max})`,
      })
    }
  }

  return {
    checks,
    violations: violationsOut,
  }
}
// ── Report ───────────────────────────────────────────────────────────────────
const blockingViolations = [
  ...paletteViolations,
  ...runtimeViolations.filter((v) => v.blocking !== false),
  ...renderedViolations.filter((v) => v.blocking !== false),
  ...coverageViolations,
]
const advisoryViolations = [
  ...runtimeViolations.filter((v) => v.blocking === false),
  ...renderedViolations.filter((v) => v.blocking === false),
  ...typographyViolations,
  ...accentViolations,
]
const quarantineResult = applyQuarantine(blockingViolations)
const debtRatchetResult = applyDebtRatchet(blockingViolations)
const effectiveBlockingViolations = [
  ...quarantineResult.unsuppressed,
  ...quarantineResult.expiredViolations,
  ...debtRatchetResult.violations,
]
const incidents = buildIncidents(effectiveBlockingViolations)

const summary = {
  generatedAt: new Date().toISOString(),
  baseUrl: BASE_URL,
  routesDiscovered: inventory.length,
  staticRoutesChecked: skipRuntime ? 0 : staticRoutes.length,
  paletteViolations: paletteViolations.length,
  typographyWarnings: typographyViolations.length,
  accentWarnings: accentViolations.length,
  availabilityViolations: runtimeViolations.filter((v) => v.dimension === 'availability').length,
  latencyWarnings: runtimeViolations.filter((v) => v.blocking === false).length,
  renderedViolations: renderedViolations.length,
  renderedCaptureFailures: renderedViolations.filter((v) => v.dimension === 'rendered-capture').length,
  renderedDarknessWarnings: renderedViolations.filter((v) => v.dimension === 'rendered-darkness').length,
  screenshotsCaptured: screenshotMetrics.size,
  advisoryWarnings: advisoryViolations.length,
  visualDiscipline: {
    routesTracked: routeVisualDiscipline.size,
    typographyViolations,
    accentViolations,
  },
  rendered: {
    screenshotsCaptured: screenshotMetrics.size,
    screenshotDir: SCREENSHOTS_DIR,
    metrics: Array.from(screenshotMetrics.entries()).map(([route, data]) => ({ route, ...data })),
  },
  coverage: {
    ...verdictTotals,
    coveragePct,
    skippedByReason: skipCounts,
    unexplainedGaps: coverageViolations.length,
    verdicts,
  },
  incidents: {
    total: incidents.length,
    byDimension: incidents.reduce((acc, incident) => {
      acc[incident.dimension] = (acc[incident.dimension] ?? 0) + 1
      return acc
    }, {}),
    top: incidents,
  },
  quarantine: {
    ...quarantineResult.stats,
    suppressed: quarantineResult.suppressed,
  },
  debtRatchet: {
    checks: debtRatchetResult.checks,
    violations: debtRatchetResult.violations,
    pass: debtRatchetResult.violations.length === 0,
  },
  blockingViolations: effectiveBlockingViolations.length,
  violations: [...blockingViolations, ...advisoryViolations],
}

fs.mkdirSync(path.dirname(path.join(ROOT, OUTPUT_JSON)), { recursive: true })
fs.writeFileSync(path.join(ROOT, OUTPUT_JSON), JSON.stringify(summary, null, 2))
writeLatestReportFiles({
  jsonPath: STATUS_JSON,
  markdownPath: STATUS_MD,
  report: summary,
  markdown: buildMarkdown(summary),
})

console.log('Luxury page sentinel')
console.log(`- routes discovered: ${summary.routesDiscovered}`)
console.log(`- static routes checked at runtime: ${summary.staticRoutesChecked}`)
console.log(`- screenshots captured: ${summary.screenshotsCaptured}`)
console.log(`- coverage: ${coveragePct}% (${verdictTotals.passed} pass, ${verdictTotals.failed} fail, ${verdictTotals.skipped} skip, ${verdictTotals.gaps} unexplained gap)`)
for (const [reason, count] of Object.entries(skipCounts)) {
  console.log(`  skip[${reason}]: ${count}`)
}
console.log(`- incidents: ${incidents.length}`)
console.log(`- quarantine: active=${quarantineResult.stats.activeEntries}, expired=${quarantineResult.stats.expiredEntries}, suppressed=${quarantineResult.stats.suppressedFindings}`)
console.log(`- debt-ratchet pass: ${summary.debtRatchet.pass}`)
for (const check of summary.debtRatchet.checks) {
  console.log(`  debt[${check.dimension}]: current=${check.current}, max=${check.max}, pass=${check.pass}`)
}
console.log(`- palette violations: ${summary.paletteViolations}`)
console.log(`- typography warnings: ${summary.typographyWarnings}`)
console.log(`- accent warnings: ${summary.accentWarnings}`)
console.log(`- availability violations: ${summary.availabilityViolations}`)
console.log(`- latency warnings: ${summary.latencyWarnings}`)
console.log(`- rendered violations: ${summary.renderedViolations} (${summary.renderedCaptureFailures} capture failures, ${summary.renderedDarknessWarnings} darkness warnings)`)
console.log(`- advisory warnings total: ${summary.advisoryWarnings}`)
for (const incident of incidents.slice(0, 15)) {
  const sample = incident.sampleRoutes.join(', ')
  console.log(`  [incident] ${incident.dimension}/${incident.scope} :: routes=${incident.routeCount} :: ${incident.signature}`)
  if (sample) console.log(`    sample: ${sample}`)
}

// ── Slack alert ──────────────────────────────────────────────────────────────
const webhook = process.env.SLACK_WEBHOOK_URL
if (webhook && effectiveBlockingViolations.length > 0) {
  const lines = incidents.slice(0, 12).map((incident) => {
    const sampleRoutes = incident.sampleRoutes.join(', ')
    const extraRoutes = incident.routeCount > incident.sampleRoutes.length ? ` +${incident.routeCount - incident.sampleRoutes.length} more` : ''
    return `• [${incident.dimension}/${incident.scope}] ${incident.routeCount} route(s) :: ${incident.signature} :: ${sampleRoutes}${extraRoutes}`
  })
  const extra = incidents.length > 12 ? `\n…and ${incidents.length - 12} more incident pattern(s)` : ''
  const skipSummary = Object.entries(skipCounts).map(([reason, count]) => `${reason}=${count}`).join(', ') || 'none'
  const text = [
    `:rotating_light: Luxury page sentinel found ${incidents.length} incident pattern(s) across ${effectiveBlockingViolations.length} blocking route findings`,
    `Base URL: ${BASE_URL}`,
    '',
    '*Executive summary*',
    effectiveBlockingViolations.length === 0
      ? '- Luxury sentinel run is stable with no blocking conformance incidents.'
      : `- Conformance risk remains elevated: ${summary.paletteViolations} palette findings, ${summary.availabilityViolations} availability findings, and ${coverageViolations.length} coverage issue(s).`,
    `Coverage: ${coveragePct}% of ${verdictTotals.total} routes (${verdictTotals.passed} pass, ${verdictTotals.failed} fail, ${verdictTotals.skipped} skip [${skipSummary}], ${verdictTotals.gaps} unexplained gap)`,
    `Routes discovered: ${summary.routesDiscovered} | Incidents: ${incidents.length} | Palette findings: ${summary.paletteViolations} | Typography warnings: ${summary.typographyWarnings} | Accent warnings: ${summary.accentWarnings} | Availability findings: ${summary.availabilityViolations} | Coverage gaps: ${coverageViolations.length}`,
    `Quarantine: active=${quarantineResult.stats.activeEntries}, expired=${quarantineResult.stats.expiredEntries}, suppressed=${quarantineResult.stats.suppressedFindings}`,
    `Debt ratchet: ${summary.debtRatchet.pass ? 'pass' : 'fail'} (${summary.debtRatchet.checks.map((c) => `${c.dimension}=${c.current}/${c.max}`).join(', ')})`,
    '',
    ...lines,
  ].join('\n') + extra
  try {
    const posted = await postSlackText({ webhookUrl: webhook, text })
    console.log(`slack alert sent: ${posted ? 'yes' : 'no'}`)
  } catch (err) {
    console.error(`slack alert failed: ${err.message}`)
  }
}

if (effectiveBlockingViolations.length > 0 && failOnBlocking && !reportOnly) {
  process.exitCode = 1
}

